window.STUDY_DATA = {"chapters": [{"id": 1, "title": "Foundations of project management", "week": "Week 1 · Sep 9", "pages": "1–46", "pdfPages": "26–71", "notes": ["Separate projects (temporary, unique outcomes) from recurring operations. Temporary refers to a finite endeavour, not a short-lived product.", "Balance scope, time, and cost, but also consider quality, risk, resources, stakeholder satisfaction, and business value.", "A program coordinates related projects for combined benefits. A portfolio selects and balances investments against organizational strategy.", "Know the ten knowledge areas: integration, scope, schedule, cost, quality, resource, communications, risk, procurement, and stakeholder management.", "Distinguish the sponsor’s backing and resources from the project manager’s coordination. Practice classifying situations, not just memorizing labels."]}, {"id": 2, "title": "The IT project context", "week": "Week 2 · Sep 16", "pages": "47–84", "pdfPages": "72–109", "notes": ["Use a systems view: the three spheres are business, organization, and technology. A technically successful solution can still fail organizationally.", "Four organizational frames: structural (roles), human resources (people’s needs), political (power and conflict), symbolic (meaning and culture).", "Functional structures give project managers limited authority; matrix structures share authority; pure project structures give them more.", "Project phases are not the five process groups. Product life cycles can outlast the projects that create products. Phase gates may continue, redirect, or stop work.", "Agile values responsiveness, collaboration, working software, and interaction without eliminating useful documentation or planning. Virtual teams need deliberate trust and communication."]}, {"id": 3, "title": "Process groups & agile", "week": "Week 2 · Sep 16", "pages": "85–150", "pdfPages": "110–175", "notes": ["Five process groups: initiating, planning, executing, monitoring and controlling, closing. They overlap and can recur within phases.", "A business case justifies an investment; a charter authorizes it. A kick-off aligns participants; it does not replace authorization.", "Executing usually consumes the most resources. Monitoring and controlling compares actual performance to plans while work continues.", "Product owner: product value and backlog priorities. Scrum master: facilitate Scrum and remove impediments. Developers: organize delivery work.", "Product backlog covers product needs; sprint backlog covers selected sprint work. Review inspects the product; retrospective improves the process; burndown shows remaining work."]}, {"id": 4, "title": "Integration management", "week": "Week 3 · Sep 23", "pages": "151–200", "pdfPages": "176–225", "notes": ["Integration reconciles cross-area trade-offs. Strategic fit should inform project selection before technical enthusiasm drives the decision.", "NPV = sum of discounted net cash flows, including the initial outflow. For rate r and period t, divide that period’s cash flow by (1+r)^t.", "Simple ROI = (benefits − costs) / costs. Simple payback is when cumulative net inflows recover the investment. Neither substitutes for every strategic criterion.", "Weighted score = sum of weight × criterion score. Weights normally sum to 100%; use consistent scales and direction.", "The charter authorizes; the management plan coordinates action. Evaluate requested changes, follow agreed approval authority, and communicate approved updates.", "Capture lessons throughout delivery. Tacit knowledge often needs interaction; explicit knowledge is readily documented. Cancelled projects still require proper closure."]}, {"id": 5, "title": "Scope management", "week": "Week 4 · Sep 30", "pages": "201–240", "pdfPages": "226–265", "notes": ["Product scope describes features; project scope describes all work needed to produce and deliver the outcome.", "Scope processes: plan scope management, collect requirements, define scope, create WBS, validate scope, control scope.", "Requirements traceability connects requirements to sources and downstream deliverables or tests. Prototypes help clarify unclear needs.", "WBS: deliverable-oriented decomposition of all approved work. Work packages are the lowest level; the WBS dictionary explains components in detail.", "Scope baseline = approved scope statement + WBS + WBS dictionary. A WBS is not an activity dependency network.", "Quality control checks correctness; scope validation obtains formal acceptance. Scope creep is uncontrolled expansion; useful-looking extras still need approval."]}, {"id": 6, "title": "Schedule management", "week": "Week 5 · Oct 7", "pages": "241–284", "pdfPages": "266–309", "notes": ["Duration is elapsed working time; effort is labor. An activity requiring 16 hours at 4 hours per day has 4 working days of duration.", "A milestone is a significant event with zero duration. Mandatory, discretionary, and external describe why dependencies exist.", "Finish-to-start, start-to-start, finish-to-finish, and start-to-finish describe relationship types. Lead allows overlap; lag imposes waiting.", "Critical path = longest duration path through the network. It controls earliest finish under the model’s assumptions and can change as work changes.", "Total float = late start − early start = late finish − early finish. Free float concerns delay without affecting the early start of a successor.", "Crashing adds resources/cost; fast tracking overlaps sequential work. Both have trade-offs. Critical chain includes resource constraints and buffers.", "PERT expected duration = (optimistic + 4 × most likely + pessimistic) / 6. Do not substitute the simple three-point average."]}, {"id": 7, "title": "Cost management", "week": "Week 8 · Oct 28", "pages": "285–326", "pdfPages": "310–351", "notes": ["Compare future relevant costs and benefits; do not continue solely because of sunk costs. Life cycle costing includes ownership beyond acquisition.", "Analogous uses similar prior work; parametric applies a rate/model; bottom-up aggregates detailed estimates.", "The cost baseline is time-phased. Contingency reserves address identified risks; management reserves address unforeseen work and are outside the baseline.", "PV = planned value; EV = budgeted value of work performed; AC = actual cost. CV = EV − AC; SV = EV − PV. Negative variances are unfavorable.", "CPI = EV / AC; SPI = EV / PV. Values below 1 are unfavorable. EAC = BAC / CPI when current cost efficiency is assumed to continue.", "EVM schedule variance is expressed in value units, not directly in days. A favorable cost indicator does not prove favorable schedule performance."]}, {"id": 8, "title": "Quality management", "week": "Week 8 · Oct 28", "pages": "327–372", "pdfPages": "352–397", "notes": ["Quality means meeting requirements and being fit for use. Grade or feature count is not the same as quality.", "Plan quality sets standards and methods; manage quality improves processes; control quality checks specific outputs.", "Pareto: rank major contributors. Cause-and-effect: potential causes. Control chart: variation over time. Scatter: relationship between variables.", "Also know checksheets, histograms, and flowcharts. Statistical sampling evaluates part of a population; correlation does not establish causation.", "DMAIC = define, measure, analyze, improve, control. Six Sigma emphasizes reducing defects and variation.", "Prevention avoids defects; appraisal evaluates conformance; internal failure is before delivery; external failure is after delivery.", "Unit testing checks components; integration checks interfaces; system testing checks the whole system; user acceptance tests focus on user acceptance."]}, {"id": 9, "title": "Resource management", "week": "Week 9 · Nov 4", "pages": "373–424", "pdfPages": "398–449", "notes": ["Maslow: physiological, safety, social, esteem, self-actualization. Herzberg: hygiene reduces dissatisfaction; achievement and growth can motivate.", "McClelland: achievement, affiliation, power. Theory X assumes control is needed; Theory Y supports self-direction and responsibility.", "Power bases: legitimate (position), reward, coercive, expert (knowledge), referent (admiration).", "RACI = responsible, accountable, consulted, informed. Clarify who performs work and who owns the outcome.", "Resource leveling resolves over-allocation and can extend duration. Acquiring obtains resources; developing improves skills and team effectiveness.", "Tuckman: forming, storming, norming, performing, adjourning. Collaboration seeks a joint solution; compromise gives up something on both sides.", "Emotional intelligence includes awareness and regulation of emotions. Physical resources also fall within the ninth edition’s resource-management scope."]}, {"id": 10, "title": "Communications management", "week": "Week 9 · Nov 4", "pages": "425–462", "pdfPages": "450–487", "notes": ["Plan communications around information needs, recipients, timing, methods, ownership, and feedback. More detail is not always better.", "Potential two-way communication channels = n(n−1)/2. To find added channels, calculate both totals and subtract.", "Interactive is two-way exchange; push sends to recipients; pull makes information available for retrieval. Sending does not prove understanding.", "Status reports describe the current position; progress reports describe work completed over a period; forecasts predict future outcomes.", "Communicate bad news promptly with evidence and options. Listen actively and confirm meaning before assuming agreement.", "Use purposeful meetings with agendas, decisions, and assigned actions. Monitor whether communication actually meets needs and adjust accordingly."]}, {"id": 11, "title": "Risk management", "week": "Week 10 · Nov 11", "pages": "463–504", "pdfPages": "488–529", "notes": ["Risks are uncertain threats or opportunities. Current problems belong in issue management; risk identification continues throughout delivery.", "The risk register records events, causes, owners, assessments, and responses. Qualitative analysis prioritizes; quantitative analysis models numerical effects.", "EMV = probability × monetary outcome, summed over outcomes. Treat a loss as negative when using signed EMV.", "Monte Carlo samples distributions repeatedly. Sensitivity analysis tests how changing inputs affects outcomes. Delphi gathers structured, often anonymous expert input.", "Threat responses include avoid, mitigate, transfer, accept, and escalate. Opportunity responses include exploit, enhance, share, accept, and escalate/elevate.", "Contingency plans respond to identified events; fallback plans apply when the initial response fails. Residual risks remain; secondary risks arise from a response."]}, {"id": 12, "title": "Procurement management", "week": "Week 11 · Nov 18", "pages": "505–538", "pdfPages": "530–563", "notes": ["Make-or-buy decisions weigh internal provision versus procurement. Include capability and strategic fit as well as direct cost.", "Fixed price generally places more defined-scope cost risk on the seller. Cost reimbursable places more on the buyer. Time and material fixes rates, not necessarily total cost.", "The procurement SOW defines contracted work. RFP seeks proposals and approaches; RFQ seeks quotes for clearly specified requirements.", "Conduct procurements obtains responses, selects sellers, and awards contracts. Predetermined evaluation criteria and bidder conferences support consistent selection.", "Control procurements monitors performance and handles changes and closure. Informal directions can create constructive changes; use proper authority and procedures.", "For a simple break-even comparison, equate total cost functions and solve. State assumptions about rates, time, and other costs."]}, {"id": 13, "title": "Stakeholder management", "week": "Week 12 · Nov 25", "pages": "539–560", "pdfPages": "564–585", "notes": ["Identify internal and external stakeholders, including opponents. The register captures identification and assessment information.", "Power-interest grid: high/high manage closely; high/low keep satisfied; low/high keep informed; low/low monitor. Reassess as circumstances change.", "Engagement levels include unaware, resistant, neutral, supportive, and leading. Compare current and desired engagement to plan action.", "Managing engagement means working with people on expectations and concerns. Monitoring engagement evaluates changing relationships and adjusts strategies.", "Issue logs track current concerns, owners, and resolution. Some stakeholder assessments are sensitive and need appropriate handling.", "Adaptive environments benefit from frequent feedback, transparent work, and timely stakeholder decisions. Do not postpone all input until final delivery."]}], "questions": [{"id": "M001", "chapter": 1, "topic": "Projects vs. operations", "section": "What Is a Project?", "stem": "A university forms a temporary team to replace its registration system. After launch, a separate team will run nightly backups and process routine support tickets. The sponsor wants both activities labeled as projects because they use the same software. Which classification best reflects the textbook?", "options": ["The replacement is a project; recurring support is operations.", "Both are projects because they involve IT.", "Neither is a project because the technology already exists.", "Only recurring support is a project."], "correct": 0, "explanation": "A project creates a unique result within a temporary effort. Repeated support sustains operations; using IT does not make an activity a project.", "type": "mcq"}, {"id": "M002", "chapter": 1, "topic": "Temporary does not mean short", "section": "Project Attributes", "stem": "A data-centre relocation is expected to take four years. The sponsor argues that such a lengthy undertaking cannot be a project. A colleague says it is still a project because it has a defined endpoint and will produce a unique relocation result. Which interpretation is most appropriate?", "options": ["The relocation becomes a program solely because it lasts four years.", "The sponsor is correct: a project must end within one year.", "The relocation is operations until its final year.", "The colleague is correct: temporary means a finite duration, not necessarily a short one."], "correct": 3, "explanation": "Temporary means the endeavour has a beginning and end. Length alone does not turn a project into operations or a program.", "type": "mcq"}, {"id": "M003", "chapter": 1, "topic": "Progressive elaboration", "section": "Project Attributes", "stem": "A team initially describes a new portal at a high level. As users are interviewed and technical uncertainties are resolved, the team refines its requirements and estimates within the approved objectives. The sponsor mistakes this normal development of detail for uncontrolled expansion. Which concept best describes the team's work?", "options": ["Project termination", "Progressive elaboration", "Scope creep", "Routine operations"], "correct": 1, "explanation": "Progressive elaboration increases detail as knowledge improves. Scope creep adds uncontrolled work; refinement within approved objectives does not necessarily expand scope.", "type": "mcq"}, {"id": "M004", "chapter": 1, "topic": "Triple constraint", "section": "Project Constraints", "stem": "A client requests two extra modules but insists that the original launch date and budget remain unchanged. The project manager explains that the request needs impact analysis before a promise can be made. Which relationship is the manager emphasizing when discussing the classical triple constraint in this situation?", "options": ["A fixed deadline automatically eliminates the cost impact of extra scope.", "Scope, time, and cost interact, so changing one can affect the others.", "Only time and cost are constraints; scope is a preference.", "Scope can change independently whenever quality remains constant."], "correct": 1, "explanation": "The classical triple constraint comprises scope, time, and cost. Extra scope can require more time or resources; constraints must be balanced rather than assumed independent.", "type": "mcq"}, {"id": "M005", "chapter": 1, "topic": "Other constraints", "section": "Project Constraints", "stem": "A security application ships on its planned date and within the approved budget. However, its authentication fails under realistic load and the customer refuses to use it. A manager declares success because two constraints were met. Which conclusion best reflects the textbook's broader view of project performance?", "options": ["Meeting time and cost always outweighs product usability.", "Any delivery on time establishes that the original scope was satisfied.", "The project succeeds if its manager signs the final report.", "Quality and stakeholder satisfaction also matter when assessing success."], "correct": 3, "explanation": "Scope, time, and cost are important but insufficient alone. Quality, acceptance, and intended value also matter; meeting two measures does not establish overall success.", "type": "mcq"}, {"id": "M006", "chapter": 1, "topic": "Stakeholders", "section": "Project Stakeholders", "stem": "A payroll replacement affects developers, employees, a software supplier, and a union that is concerned about data access. The manager proposes listing only people who directly work on the software because other groups cannot alter code. Which response gives the strongest basis for identifying stakeholders?", "options": ["Include only people with tasks in the project schedule.", "Include people or groups affected by the project, even if they do no project work.", "Include only employees who approve project invoices.", "Exclude any group that opposes the proposed system."], "correct": 1, "explanation": "Stakeholders include those involved in or affected by the project, including external parties and opponents. Assignment to a task is not the defining criterion.", "type": "mcq"}, {"id": "M007", "chapter": 1, "topic": "Project sponsor", "section": "Project Attributes", "stem": "An executive secures organizational backing and funding for a student-services system. The project manager coordinates the team, while a lead analyst develops requirements. During a governance review, the team needs to identify the person providing sponsorship rather than day-to-day coordination. Which person best fits the project sponsor role described here?", "options": ["The executive providing support and funding", "The person preparing the daily task board", "The developer assigned the greatest number of tasks", "The analyst documenting the detailed requirements"], "correct": 0, "explanation": "The sponsor provides direction and backing, often including financial resources. The project manager coordinates delivery; an assigned technical task does not create sponsorship.", "type": "mcq"}, {"id": "M008", "chapter": 1, "topic": "Program management", "section": "Programs", "stem": "A retailer runs related projects for online checkout, warehouse integration, and delivery tracking. A manager coordinates their dependencies so that the combined service produces benefits that separate delivery would miss. The organization is not simply choosing which investments to fund. What management approach is most directly illustrated by this arrangement?", "options": ["Program management", "Operations management", "Standalone project scheduling", "Portfolio selection only"], "correct": 0, "explanation": "A program coordinates related projects to obtain combined benefits and control. A portfolio focuses on selecting and balancing investments against strategy, whether related or not.", "type": "mcq"}, {"id": "M009", "chapter": 1, "topic": "Portfolio management", "section": "Project Portfolio Management", "stem": "Executives compare a security upgrade, a new mobile app, and an unrelated payroll replacement. Limited funding forces them to balance risk, expected returns, and strategic fit across the whole organization. No shared technical deliverable links the three efforts. Which type of management is central to this decision?", "options": ["Program management solely because there are three projects", "Scope validation within a single project", "Project portfolio management", "Daily operations scheduling"], "correct": 2, "explanation": "Portfolio management treats projects and programs as investments supporting strategy. Related technical work is not required, unlike the coordinated benefits rationale for a program.", "type": "mcq"}, {"id": "M010", "chapter": 1, "topic": "Tactical vs. strategic", "section": "Project Portfolio Management", "stem": "A project manager asks whether the approved portal can be delivered within its budget. A portfolio board asks whether the portal should remain funded instead of another investment. Both questions concern the same initiative, but their decision levels differ. Which statement best distinguishes the two perspectives in the textbook?", "options": ["Project management emphasizes delivery objectives; portfolio management emphasizes strategic investment choices.", "Project management selects corporate strategy; portfolios assign individual activities.", "Portfolio management begins only after all projects have closed.", "Both questions are exclusively about scope validation."], "correct": 0, "explanation": "Delivering a project well is a tactical concern; selecting the right mix of projects to support the enterprise is strategic. The questions are complementary, not interchangeable.", "type": "mcq"}, {"id": "M011", "chapter": 1, "topic": "Integration management", "section": "Project Management Knowledge Areas", "stem": "An approved interface change affects testing, training, procurement, costs, and the release date. Several specialists optimize their own plans independently, producing inconsistent commitments. The project manager brings these decisions together and resolves trade-offs across areas. Which knowledge area most directly captures the coordinating responsibility in this scenario?", "options": ["Project procurement management only", "Project resource management only", "Project integration management", "Project scope management only"], "correct": 2, "explanation": "Integration coordinates the project as a whole. Scope, procurement, and resources each cover part of the problem but cannot alone reconcile all cross-area trade-offs.", "type": "mcq"}, {"id": "M012", "chapter": 1, "topic": "Knowledge areas vs. process groups", "section": "Project Management Knowledge Areas", "stem": "A new coordinator prepares a study chart with columns labeled scope, cost, risk, and communications. A teammate says these are the phases that every project must complete once in that order. The coordinator must correct the chart before sharing it. What is the most accurate explanation?", "options": ["They are knowledge areas, not a required sequence of project phases.", "They are four of the five process groups.", "They are organizational structures ordered by manager authority.", "They represent the only project constraints."], "correct": 0, "explanation": "Knowledge areas organize subject matter and responsibilities. Process groups organize types of management activity, and project phases describe a life cycle; these are different classifications.", "type": "mcq"}, {"id": "M013", "chapter": 1, "topic": "Leadership skills", "section": "Suggested Skills for Project Managers", "stem": "An excellent programmer becomes project manager but spends most meetings correcting code. Dependencies remain unresolved because the manager avoids negotiation and cannot explain priorities to users or sponsors. The organization considers giving the manager another programming course. Which development priority better addresses the situation described here?", "options": ["More coding expertise as the sole development priority", "Communication, leadership, and stakeholder coordination skills", "Delegating every cross-team decision to the software tool", "Avoiding all user contact to protect technical focus"], "correct": 1, "explanation": "Technical competence helps, but project managers need communication, leadership, and general management skills. More coding alone does not address the coordination failure.", "type": "mcq"}, {"id": "M014", "chapter": 1, "topic": "Ethical reporting", "section": "Ethics in Project Management", "stem": "A manager discovers that a milestone will probably be missed. A colleague suggests leaving the status green until after the funding meeting because the team might recover later. There is no evidence that recovery is likely. Which action best reflects responsible and honest project management reporting in this case?", "options": ["Report only positive indicators until sponsors ask for details.", "Report the current evidence, uncertainty, and corrective options accurately.", "Keep the status green because the delay is not yet certain.", "Remove the milestone from the report without explanation."], "correct": 1, "explanation": "Ethical reporting represents the evidence honestly, including uncertainty. Concealing an expected problem or removing it to mislead stakeholders prevents informed decisions.", "type": "mcq"}, {"id": "M015", "chapter": 1, "topic": "Tools and judgment", "section": "Project Management Software", "stem": "A team buys sophisticated scheduling software after several failed implementations. The sponsor assumes that installing it guarantees better requirements, motivated staff, and successful delivery. The project manager needs to set realistic expectations before the next project begins. Which response best matches the textbook's treatment of project management software?", "options": ["Software automatically resolves disagreement about project requirements.", "A detailed schedule guarantees that the project will meet all objectives.", "Once software is installed, stakeholder involvement becomes unnecessary.", "Software supports management but does not replace sound processes and people skills."], "correct": 3, "explanation": "Tools help organize and analyze work, but project success also requires judgment, stakeholder involvement, leadership, and appropriate processes. Software alone provides none of those guarantees.", "type": "mcq"}, {"id": "M016", "chapter": 2, "topic": "Three-sphere model", "section": "The Three-Sphere Model for Systems Management", "stem": "A college selects a technically impressive tablet platform without checking affordability for students or whether departments can support it. The technology tests well, but adoption fails. The review team wants a framework that would have exposed the neglected issues before selection. Which combination best represents the textbook's three-sphere model?", "options": ["People, profit, and procurement", "Initiation, planning, and execution", "Scope, schedule, and cost", "Business, organization, and technology"], "correct": 3, "explanation": "The three-sphere model considers business, organizational, and technological issues together. The triple constraint is a different model and does not name these spheres.", "type": "mcq"}, {"id": "M017", "chapter": 2, "topic": "Systems thinking", "section": "What Is a Systems Approach?", "stem": "A hospital's IT team improves server response time by changing a workflow, but the change increases nurses' administrative work and delays treatment. Technical performance improves while the broader service suffers. What should a systems-oriented project manager emphasize when evaluating the proposed solution and its success across the hospital?", "options": ["Evaluate effects on the wider organization and interacting components.", "Optimize each technical component independently of its users.", "Use server response time as the only success measure.", "Ignore work outside the IT department's authority."], "correct": 0, "explanation": "A systems view evaluates how components interact within a larger whole. Local technical improvement can harm business or organizational outcomes if interdependencies are ignored.", "type": "mcq"}, {"id": "M018", "chapter": 2, "topic": "Structural frame", "section": "The Four Frames of Organizations", "stem": "Two departments repeatedly duplicate approval work. The project manager examines reporting lines, formal responsibilities, and decision rules, then revises the division of work. The focus is on how the organization is arranged to achieve its goals rather than on workplace rituals or personal alliances. Which organizational frame is being used?", "options": ["Symbolic frame", "Human resources frame", "Political frame", "Structural frame"], "correct": 3, "explanation": "The structural frame concerns roles, responsibilities, coordination, and formal arrangements. Symbolic concerns meaning; political concerns power; human resources concerns the fit between people and organization.", "type": "mcq"}, {"id": "M019", "chapter": 2, "topic": "Political frame", "section": "The Four Frames of Organizations", "stem": "Two executives support competing systems because each wants control of a limited capital budget. The project manager maps coalitions, influence, and competing interests before trying to build agreement. A revised organization chart alone would not address the dispute. Which organizational frame best explains the manager's analysis in this situation?", "options": ["Structural frame only", "Political frame", "Symbolic frame", "Technical frame"], "correct": 1, "explanation": "The political frame focuses on power, conflict, coalitions, and scarce resources. Formal structure alone does not explain the competing agendas described.", "type": "mcq"}, {"id": "M020", "chapter": 2, "topic": "Symbolic frame", "section": "The Four Frames of Organizations", "stem": "Employees resist a new process because it removes a long-standing ceremony that celebrates successful releases. The project manager discovers that the ceremony expresses professional pride and belonging, although it has no formal role in approvals. Which frame is most useful for understanding the importance employees attach to this practice?", "options": ["Financial frame", "Symbolic frame", "Political frame", "Structural frame"], "correct": 1, "explanation": "The symbolic frame addresses meaning, culture, rituals, and symbols. The ceremony matters because of what it represents, rather than its formal authority or cost.", "type": "mcq"}, {"id": "M021", "chapter": 2, "topic": "Human resources frame", "section": "The Four Frames of Organizations", "stem": "A technically sound reorganization leaves analysts feeling that their skills are wasted and their growth needs ignored. The project manager redesigns work and training to better fit employees' needs with organizational requirements. Which frame most directly guides this response, given that the central concern is people and their relationship with the organization?", "options": ["Human resources frame", "Symbolic frame only", "Political frame only", "Structural frame only"], "correct": 0, "explanation": "The human resources frame focuses on harmony between organizational needs and people's needs. Training and meaningful use of skills address this fit directly.", "type": "mcq"}, {"id": "M022", "chapter": 2, "topic": "Functional structure", "section": "Organizational Structures", "stem": "Specialists report to department heads, who control their assignments and performance evaluations. A project coordinator must request people from those heads and has little independent authority over them. The company has no dedicated project teams. Which organizational structure best describes the setting and the coordinator's limited authority here?", "options": ["Pure project organization", "Strong matrix with dominant project authority", "Projectized organization with full-time project control", "Functional organization"], "correct": 3, "explanation": "A functional organization groups people by specialization and gives functional managers strong authority. Pure project structures give project managers much more control.", "type": "mcq"}, {"id": "M023", "chapter": 2, "topic": "Matrix structure", "section": "Organizational Structures", "stem": "A business analyst reports to a functional manager for professional development and also works under a project manager for delivery commitments. Both managers negotiate priorities and resource availability. The analyst is not permanently transferred to a separate project department. Which organizational structure is most clearly illustrated by this dual relationship?", "options": ["Matrix organization", "Informal organization without management authority", "Pure functional organization with no project role", "Pure project organization"], "correct": 0, "explanation": "A matrix combines functional and project dimensions, often creating dual reporting or shared authority. The precise balance depends on whether the matrix is weak, balanced, or strong.", "type": "mcq"}, {"id": "M024", "chapter": 2, "topic": "Projectized authority", "section": "Organizational Structures", "stem": "A consulting firm forms a dedicated team for a large implementation. Team members work full time on it, and the project manager controls most project decisions and resources. An analyst compares this arrangement with a department-based structure. In which setting does the project manager generally have the greatest authority?", "options": ["An organization where the manager is only an expediter", "A weak matrix organization", "A pure functional organization", "A pure project organization"], "correct": 3, "explanation": "The textbook associates the greatest project-manager authority with a pure project organization. Functional and weak-matrix structures reserve more authority for functional management.", "type": "mcq"}, {"id": "M025", "chapter": 2, "topic": "Organizational culture", "section": "Organizational Culture", "stem": "Staff hide cross-team problems because the company rewards individual departmental results and penalizes anyone who raises conflict. Schedules look healthy until dependencies fail. The project manager proposes stronger cooperation and constructive discussion. Which cultural change is most consistent with a setting that supports effective project management across departments?", "options": ["Reward team results and encourage constructive discussion of problems.", "Reduce integration between departments to avoid dependence.", "Reward silence about disagreements to preserve harmony.", "Treat all risk-taking and disagreement as misconduct."], "correct": 0, "explanation": "Group emphasis, integration, and constructive tolerance of conflict help expose and solve project problems. Suppressing disagreement can hide issues without removing them.", "type": "mcq"}, {"id": "M026", "chapter": 2, "topic": "Executive commitment", "section": "The Importance of Top Management Commitment", "stem": "A project needs resources from three departments, but each department refuses to release staff. The project manager has exhausted routine negotiations and the project is strategically important. The sponsor has so far limited involvement to launch-day encouragement. Which additional support would best demonstrate meaningful top-management commitment in this case?", "options": ["Buy a scheduling tool and regard the conflict as solved.", "Ask the manager to compensate with more detailed status slides.", "Resolve cross-department priorities and secure the agreed resources.", "Avoid involvement because executives should never influence resources."], "correct": 2, "explanation": "Top management can remove organizational obstacles and help obtain resources. Encouragement or software alone does not resolve competing departmental priorities.", "type": "mcq"}, {"id": "M027", "chapter": 2, "topic": "Phase gates", "section": "The Importance of Project Phases and Management Reviews", "stem": "At the end of a feasibility phase, evidence shows that a proposed platform no longer supports the business strategy. The team argues that the next phase must begin because the project already has a name and budget. What is the most appropriate purpose of the management review at this boundary?", "options": ["Certify that any prior spending must be recovered by continuing.", "Decide whether to continue, redirect, or terminate based on current evidence.", "Automatically approve the next phase because funding once existed.", "Replace all future monitoring with a single approval."], "correct": 1, "explanation": "Phase-end reviews are decision points, often called gates or kill points. They test continued viability; past authorization does not make continuation automatic.", "type": "mcq"}, {"id": "M028", "chapter": 2, "topic": "Project vs. product life cycle", "section": "Project and Product Life Cycles", "stem": "A team finishes developing and launching a mobile application, hands it to operations, and closes the delivery project. The application will remain in use for years and receive future upgrades through other projects. Which statement best distinguishes the two life cycles in this example without confusing delivery with ongoing use?", "options": ["Every product must be developed within a single continuous project.", "The product life cycle can extend beyond the project that created it.", "The product life cycle must end when the delivery project closes.", "Project and product life cycles are always identical."], "correct": 1, "explanation": "The project has its own phases and endpoint. The product can continue through use, maintenance, evolution, and retirement after the creation project ends.", "type": "mcq"}, {"id": "M029", "chapter": 2, "topic": "Agile values", "section": "The Manifesto for Agile Software Development", "stem": "A team claims to be agile and therefore refuses to document anything or make a plan. Users cannot understand decisions and dependencies are missed. The manager recalls that the Agile Manifesto expresses relative preferences, not a ban on the items on the right. Which response best fits that interpretation?", "options": ["Treat contract negotiation as the only source of customer input.", "Value working software and responsiveness while retaining useful plans and documentation.", "Require a fully fixed plan before any customer collaboration.", "Eliminate all documentation and planning to comply with agile."], "correct": 1, "explanation": "Agile values some things more than others; it does not declare plans, tools, contracts, or documentation worthless. Useful planning and documentation remain appropriate.", "type": "mcq"}, {"id": "M030", "chapter": 2, "topic": "Virtual teams", "section": "Virtual Teams", "stem": "A project brings together developers in three time zones who rarely meet physically. Informal questions remain unanswered overnight, and some members feel isolated. The manager must address risks inherent in this working arrangement rather than assume that a shared task board is enough. Which action is most directly helpful here?", "options": ["Agree communication practices and build relationships across locations.", "Assume remote members need no interpersonal interaction.", "Require all problems to wait for the final project review.", "Evaluate collaboration only by the number of uploaded files."], "correct": 0, "explanation": "Virtual teams need deliberate communication, trust, and coordination across distance and time. Tools support this work but do not remove social or timing challenges.", "type": "mcq"}, {"id": "M031", "chapter": 3, "topic": "Initiating", "section": "Project Management Process Groups", "stem": "A sponsor and manager are defining a new initiative, identifying key stakeholders, and obtaining formal authorization before detailed planning proceeds. A colleague classifies this work as execution because people are already doing tasks. Which process group most directly describes these activities when they establish and authorize the project or phase?", "options": ["Monitoring and controlling", "Initiating", "Executing", "Closing"], "correct": 1, "explanation": "Initiating defines and authorizes a project or phase. Simply performing work does not make every activity part of the executing process group.", "type": "mcq"}, {"id": "M032", "chapter": 3, "topic": "Planning", "section": "Project Management Process Groups", "stem": "Following authorization, the team determines the work, dependencies, budget, risks, and approach needed to achieve the objectives. Developers have not yet started building the product. Which process group best describes this coordinated effort to establish how the project will be carried out and managed against its requirements?", "options": ["Initiating only", "Closing", "Executing only", "Planning"], "correct": 3, "explanation": "Planning establishes and refines objectives and determines the actions needed to attain them. It is more detailed than initial authorization and distinct from producing the deliverables.", "type": "mcq"}, {"id": "M033", "chapter": 3, "topic": "Executing", "section": "Project Management Process Groups", "stem": "The team builds the approved portal, coordinates assigned resources, and carries out the activities in its management plan. At the same time, a separate review checks performance against baselines. Which process group most directly covers the work of creating the deliverables and coordinating people to carry out the plan?", "options": ["Closing", "Monitoring and controlling only", "Executing", "Initiating"], "correct": 2, "explanation": "Executing carries out the plan and produces work results. Checking those results against the plan belongs to monitoring and controlling, even when both occur together.", "type": "mcq"}, {"id": "M034", "chapter": 3, "topic": "Monitoring and controlling", "section": "Project Management Process Groups", "stem": "During development, the manager compares actual progress with the baseline, investigates a schedule variance, and recommends corrective action. The project is neither being newly authorized nor formally closed. Which process group best captures this ongoing assessment and adjustment of work while the team continues to build the product?", "options": ["Initiating", "Monitoring and controlling", "Closing", "Planning only"], "correct": 1, "explanation": "Monitoring and controlling tracks performance, identifies deviations, and supports corrective action. It occurs throughout the project rather than only after execution.", "type": "mcq"}, {"id": "M035", "chapter": 3, "topic": "Closing", "section": "Project Closing", "stem": "A customer accepts a completed system. The manager still needs to arrange handover, archive records, document lessons, and release resources. A developer argues that management work ended when the last feature passed its test. Which process group covers the remaining formal activities necessary to finish the project properly?", "options": ["Initiating", "Planning the original scope", "Closing", "Executing a new project"], "correct": 2, "explanation": "Closing finalizes project or phase activities and includes appropriate handover and records. Technical completion alone does not perform administrative closure.", "type": "mcq"}, {"id": "M036", "chapter": 3, "topic": "Overlapping groups", "section": "Project Management Process Groups", "stem": "A student draws five non-overlapping blocks and says a project cannot return to planning after execution starts. In a real project, the team refines later work while developing earlier deliverables and continuously reviewing performance. Which correction best describes how process groups relate over the life of a project?", "options": ["Each occurs exactly once and can never overlap.", "They overlap and can recur within project phases.", "Only monitoring occurs repeatedly; planning cannot recur.", "They are identical to five mandatory product development phases."], "correct": 1, "explanation": "Process groups are interlinked management activities, not a rigid one-time phase sequence. Planning and other groups can recur as a project develops.", "type": "mcq"}, {"id": "M037", "chapter": 3, "topic": "Resource intensity", "section": "Project Management Process Groups", "stem": "A sponsor reviewing a typical project's effort distribution expects the largest share of time and resources to be spent formally authorizing it. The manager explains that the work of carrying out the plan usually dominates. Which process group generally consumes the most resources according to the textbook's discussion?", "options": ["Executing", "Initiating", "Monitoring and controlling in every project", "Closing"], "correct": 0, "explanation": "Executing generally consumes the most resources and time. Initiation is important but usually much smaller; actual distributions can differ by project.", "type": "mcq"}, {"id": "M038", "chapter": 3, "topic": "Methodology vs. standard", "section": "Developing an IT Project Management Methodology", "stem": "An organization wants detailed procedures, templates, responsibilities, and tools for delivering its IT projects. A manager suggests tailoring an approach using the PMBOK Guide as a foundation. A colleague says a standard must be copied as a complete, identical workflow for every organization. Which interpretation is more appropriate?", "options": ["Use a methodology only when no standards exist.", "Choose software first and let its defaults determine every process.", "Tailor a methodology to organizational needs using relevant standards as guidance.", "Treat the standard as a mandatory identical workflow for all projects."], "correct": 2, "explanation": "A methodology specifies how work is carried out in a context. Standards inform it, but methods should be tailored to organizational and project needs.", "type": "mcq"}, {"id": "M039", "chapter": 3, "topic": "Business case", "section": "Project Pre-Initiation and Initiation", "stem": "Before committing to a new internal service, executives ask why it is needed, what benefits it should deliver, and whether expected value justifies the investment. The team has not yet produced a detailed schedule or work package list. Which document is most directly suited to presenting this justification for the proposed effort?", "options": ["Sprint backlog", "Business case", "WBS dictionary", "Final lessons-learned report"], "correct": 1, "explanation": "The business case explains the rationale and expected value of an investment. A charter authorizes a project; schedules and WBS details support later delivery planning.", "type": "mcq"}, {"id": "M040", "chapter": 3, "topic": "Kick-off meeting", "section": "Holding a Project Kick-Off Meeting", "stem": "A newly authorized team includes business representatives and technical staff who have not worked together. The manager brings them together to discuss objectives, roles, working relationships, and the planned approach. The meeting does not replace formal authorization. What is the main purpose of this project kick-off meeting?", "options": ["Guarantee that requirements can never change.", "Establish a shared understanding and working basis for the project.", "Formally accept all future deliverables in advance.", "Replace the need for a charter or management plan."], "correct": 1, "explanation": "A kick-off aligns people on the project and how they will work together. It neither pre-accepts outputs nor freezes all future requirements.", "type": "mcq"}, {"id": "M041", "chapter": 3, "topic": "Product owner", "section": "Scrum Roles, Artifacts, and Ceremonies", "stem": "Several users request different features for the next increment of an internal application. Someone must represent customer interests and prioritize the product backlog based on value. The developers will determine how to carry out the selected work. Which Scrum role is most directly associated with prioritizing these product needs?", "options": ["Procurement officer", "Scrum master", "Product owner", "Functional auditor"], "correct": 2, "explanation": "The product owner represents product interests and prioritizes the backlog. The Scrum master facilitates the process; developers organize how to deliver the work.", "type": "mcq"}, {"id": "M042", "chapter": 3, "topic": "Scrum master", "section": "Scrum Roles, Artifacts, and Ceremonies", "stem": "A Scrum team is blocked by repeated interruptions and confusion about its agreed practices. A team member helps remove impediments and coaches the group in using Scrum, without taking over the customer's prioritization role. Which role is best represented by these facilitation and support activities in the textbook's agile case discussion?", "options": ["Product owner", "Project sponsor", "Contract seller", "Scrum master"], "correct": 3, "explanation": "The Scrum master facilitates Scrum and helps remove impediments. The product owner prioritizes product value and needs; the roles are distinct.", "type": "mcq"}, {"id": "M043", "chapter": 3, "topic": "Product vs. sprint backlog", "section": "Scrum Roles, Artifacts, and Ceremonies", "stem": "A product has a long ordered list of possible enhancements. For the next sprint, the team selects a smaller collection and plans the associated tasks. A new analyst calls both lists the same artifact. Which distinction most accurately describes the full product list and the work chosen for the current sprint?", "options": ["The product backlog can exist only after the last sprint ends.", "The product backlog spans product needs; the sprint backlog covers the selected sprint work.", "Both lists are final acceptance records.", "The sprint backlog contains all future product needs; the product backlog covers only today."], "correct": 1, "explanation": "The product backlog contains the broader ordered product work. The sprint backlog is the work selected and planned for a particular sprint.", "type": "mcq"}, {"id": "M044", "chapter": 3, "topic": "Review vs. retrospective", "section": "Scrum Roles, Artifacts, and Ceremonies", "stem": "At the end of an iteration, the team first demonstrates the increment to stakeholders and gathers feedback. It then holds a separate conversation about collaboration and ways to improve its own process. Which pair of Scrum events best matches these two purposes in the order described by the scenario?", "options": ["Daily scrum, then project authorization", "Sprint retrospective, then sprint review", "Sprint review, then sprint retrospective", "Sprint planning, then procurement review"], "correct": 2, "explanation": "The sprint review inspects the product increment with stakeholders. The retrospective inspects and improves the team's way of working; a daily scrum has a different purpose.", "type": "mcq"}, {"id": "M045", "chapter": 3, "topic": "Burndown chart", "section": "Scrum Roles, Artifacts, and Ceremonies", "stem": "A team plots the amount of work still remaining each day in a sprint. The line stays flat for several days, prompting discussion about impediments. It is not plotting total money spent or cumulative completed features. Which agile artifact is most directly being used to visualize the progress described here?", "options": ["Cost baseline", "Burndown chart", "Stakeholder register", "Responsibility assignment matrix"], "correct": 1, "explanation": "A burndown chart displays remaining work over time. A flat segment suggests remaining work is not decreasing, although the team must investigate why.", "type": "mcq"}, {"id": "M046", "chapter": 4, "topic": "Strategic alignment", "section": "Strategic Planning", "stem": "A technically exciting proposal promises impressive features but contributes little to the organization's stated priorities. Another proposal directly supports a core business objective with fewer novel features. Before evaluating implementation details, which consideration should guide the organization's selection discussion according to the textbook's treatment of IT strategic planning?", "options": ["Preference for the newest available technology", "The personal preference of the most senior programmer", "The proposal with the longest activity list", "Alignment with the organization's business strategy"], "correct": 3, "explanation": "IT projects should support business strategy. Novel technology and long task lists are not substitutes for organizational value and alignment.", "type": "mcq"}, {"id": "M047", "chapter": 4, "topic": "SWOT analysis", "section": "Strategic Planning", "stem": "A company reviewing potential projects lists experienced developers, weak legacy documentation, an emerging customer market, and a new competing platform. It wants to distinguish internal characteristics from external conditions. Which classification correctly identifies the emerging market and the new competitor within a SWOT analysis of this organization?", "options": ["Threat and strength, respectively", "Weakness and opportunity, respectively", "Opportunity and threat, respectively", "Strength and weakness, respectively"], "correct": 2, "explanation": "Opportunities and threats arise from external conditions. Strengths and weaknesses describe internal capabilities or limitations; the market and competitor are external.", "type": "mcq"}, {"id": "M048", "chapter": 4, "topic": "NPV calculation", "section": "Net Present Value Analysis", "stem": "A project requires $10,000 immediately and is expected to return $6,000 at the end of each of the next two years. Use a 10% annual discount rate and assume no other cash flows. The sponsor wants the value in today's dollars rather than the undiscounted profit. What is the approximate net present value?", "options": ["$413 negative", "$10,413 positive", "$413 positive", "$2,000 positive"], "correct": 2, "explanation": "NPV = -10,000 + 6,000/1.10 + 6,000/1.10² = $413.22. $2,000 ignores discounting; $10,413 excludes the initial outflow.", "type": "mcq"}, {"id": "M049", "chapter": 4, "topic": "NPV interpretation", "section": "Net Present Value Analysis", "stem": "Two mutually exclusive projects have equally credible estimates and satisfy mandatory requirements. At the chosen discount rate, project A has an NPV of $40,000 and project B has an NPV of $65,000. If management selects only by NPV, which recommendation follows from these figures under the stated assumptions?", "options": ["Choose whichever has the larger undiscounted cost.", "Choose B because its NPV is higher.", "Reject both because positive NPV signals a loss.", "Choose A because a lower positive NPV is always better."], "correct": 1, "explanation": "Higher positive NPV indicates more discounted net value at the selected rate. Other criteria can matter, but the question explicitly isolates NPV.", "type": "mcq"}, {"id": "M050", "chapter": 4, "topic": "Return on investment", "section": "Return on Investment", "stem": "An internal project has estimated total benefits of $180,000 and total costs of $120,000. For this question, use the simple ROI formula without discounting. A sponsor mistakenly divides costs by benefits. What is the correct ROI when calculated as net benefits divided by total costs for this proposal?", "options": ["66.7%", "150%", "50%", "33.3%"], "correct": 2, "explanation": "ROI = (180,000 - 120,000)/120,000 = 0.50. Benefits divided by costs gives 150%, but ROI uses net benefits in the numerator.", "type": "mcq"}, {"id": "M051", "chapter": 4, "topic": "Payback period", "section": "Payback Analysis", "stem": "A proposed automation requires an immediate $90,000 investment and produces $30,000 in net savings at each year end. Ignore discounting, taxes, and any other cash flows. Management asks when cumulative savings first recover the initial investment, rather than which project creates the most total value. What is the simple payback period?", "options": ["4 years", "1 year", "2 years", "3 years"], "correct": 3, "explanation": "After three year-end receipts, savings total $90,000. Payback measures cost recovery time; it does not by itself measure all lifetime value.", "type": "mcq"}, {"id": "M052", "chapter": 4, "topic": "Weighted scoring", "section": "Using a Weighted Scoring Model", "stem": "A selection model gives strategic fit a weight of 60% and financial return a weight of 40%. On a common 1–5 scale, A scores 5 and 2, while B scores 3 and 4. Higher totals are better. Which result follows when the weights are applied to the two criteria?", "options": ["B scores 3.8 and outranks A at 3.4.", "A scores 7 and outranks B at 6.", "Both score 3.5 because their unweighted totals match.", "A scores 3.8 and outranks B at 3.4."], "correct": 3, "explanation": "A = .6×5 + .4×2 = 3.8; B = .6×3 + .4×4 = 3.4. Equal unweighted sums need not produce equal weighted scores.", "type": "mcq"}, {"id": "M053", "chapter": 4, "topic": "Project charter", "section": "Developing a Project Charter", "stem": "A team has an attractive business case but lacks formal authority to begin the project and apply organizational resources. The sponsor asks for a document that recognizes the project's existence and establishes high-level objectives and responsibility. Which document most directly serves this authorization purpose before detailed planning is completed?", "options": ["Project charter", "Final acceptance report", "Daily progress log", "Detailed WBS dictionary"], "correct": 0, "explanation": "The charter formally authorizes the project and establishes high-level information and authority. A business case justifies an investment but does not by itself perform this authorization.", "type": "mcq"}, {"id": "M054", "chapter": 4, "topic": "Management plan", "section": "Developing a Project Management Plan", "stem": "The scope plan assumes one release, the schedule assumes two releases, and the procurement plan expects a supplier after testing begins. Each individual document looks detailed, but together they are inconsistent. Which integration activity is most directly needed to combine these components into a coherent basis for action?", "options": ["Replace the plan with the charter's high-level summary.", "Validate the final deliverables immediately.", "Develop and coordinate the project management plan.", "Archive the conflicting documents without resolving them."], "correct": 2, "explanation": "Developing the management plan coordinates subsidiary plans into a consistent whole. Detail in separate documents does not ensure that their assumptions and commitments agree.", "type": "mcq"}, {"id": "M055", "chapter": 4, "topic": "Integrated change control", "section": "Performing Integrated Change Control", "stem": "A customer requests an extra reporting feature after the baseline is approved. It appears useful but may delay testing and require more supplier work. The developer wants to implement it immediately to maintain goodwill. What should the project manager do before authorizing implementation under the established change-control approach?", "options": ["Let the requesting customer bypass every project control.", "Assess impacts and route the request through the agreed approval process.", "Implement it first and update the baseline only if someone objects.", "Reject it automatically because baselines can never change."], "correct": 1, "explanation": "Changes should be evaluated across affected areas and approved through the established process. Baselines can change, but unreviewed implementation creates uncontrolled commitments.", "type": "mcq"}, {"id": "M056", "chapter": 4, "topic": "Change control board", "section": "Change Control System", "stem": "An organization names a group of representatives to review proposed baseline changes, evaluate their implications, and approve or reject them under defined authority. The group does not write every line of code or replace the whole project team. What is the name of this governance mechanism in the textbook?", "options": ["Quality inspection sample", "Change control board", "Functional resource pool", "Scrum development team"], "correct": 1, "explanation": "A change control board reviews and decides change requests within its assigned authority. It is part of the change-control system, not the delivery team itself.", "type": "mcq"}, {"id": "M057", "chapter": 4, "topic": "Configuration management", "section": "Change Control System", "stem": "Two teams are testing different versions of a supposedly identical interface specification. Nobody can tell which version is approved or how it changed. The manager introduces identification, version tracking, and control of the relevant product characteristics. Which practice most directly addresses this need alongside the broader change-control process?", "options": ["Configuration management", "Payback analysis", "Resource leveling", "Stakeholder segmentation"], "correct": 0, "explanation": "Configuration management identifies and controls product characteristics and their versions. General change approval is insufficient if teams cannot identify the approved configuration.", "type": "mcq"}, {"id": "M058", "chapter": 4, "topic": "Tacit knowledge", "section": "Managing Project Knowledge", "stem": "A senior analyst can diagnose integration failures through experience but has difficulty explaining every cue in a written checklist. Before the analyst leaves, the manager arranges paired work, demonstrations, and discussion with colleagues. What type of knowledge is especially being transferred through these direct interactions rather than through documentation alone?", "options": ["A formally approved scope change", "A cost baseline", "Tacit knowledge", "Explicit knowledge only"], "correct": 2, "explanation": "Tacit knowledge is personal and difficult to codify fully. Interaction and experience can transfer it; explicit knowledge is more readily recorded in documents or other formal representations.", "type": "mcq"}, {"id": "M059", "chapter": 4, "topic": "Lessons during delivery", "section": "Managing Project Knowledge", "stem": "An implementation team discovers a better way to coordinate vendor testing halfway through the project. The manager considers withholding the insight until the final report because lessons are supposedly a closing-only task. Which response best uses project knowledge while delivery is still underway and other teams could benefit?", "options": ["Treat every lesson as a mandatory baseline change.", "Delete the lesson if the current milestone succeeds.", "Record and share the lesson now, then update it as needed.", "Wait until closure before anyone may apply the lesson."], "correct": 2, "explanation": "Knowledge management and lessons capture can occur throughout a project. Waiting until closure loses opportunities to improve current and related work.", "type": "mcq"}, {"id": "M060", "chapter": 4, "topic": "Closure after cancellation", "section": "Closing Projects or Phases", "stem": "A sponsor cancels a project after a strategic change. Some work is unfinished, but the team still has supplier commitments, useful records, and resources to release. A manager suggests simply stopping meetings and walking away. Which response best reflects the need for project integration and formal closure in this situation?", "options": ["Skip all closure because no final product was delivered.", "Treat cancellation as proof that all contracts automatically disappear.", "Close the project appropriately, documenting outcomes and handling remaining commitments.", "Keep charging the project indefinitely until its original scope is finished."], "correct": 2, "explanation": "Cancelled projects still require orderly closure, records, handover where appropriate, and resolution of commitments. Cancellation does not automatically erase contractual or administrative obligations.", "type": "mcq"}, {"id": "M061", "chapter": 5, "topic": "Product vs. project scope", "section": "What Is Project Scope Management?", "stem": "A specification describes the features of a booking application, while a delivery plan includes training, migration, testing, and implementation work. A sponsor assumes that these documents describe exactly the same thing. Which distinction best separates the characteristics of the application from the work needed to produce and deliver it?", "options": ["Product scope is the budget; project scope is the schedule.", "Project scope describes features only; product scope lists all project activities.", "Both terms refer only to the final software code.", "Product scope describes features; project scope describes the work needed."], "correct": 3, "explanation": "Product scope concerns the product's features and functions. Project scope covers the work needed to deliver it, including work such as training and migration.", "type": "mcq"}, {"id": "M062", "chapter": 5, "topic": "Scope management plan", "section": "Planning Scope Management", "stem": "A team is not yet deciding the detailed features of its system. Instead, it agrees how scope will be defined, how the WBS will be created, how acceptance will occur, and how scope changes will be controlled. Which planning output is most directly concerned with these procedures for managing scope?", "options": ["Product prototype", "Activity network diagram", "Scope management plan", "Final accepted deliverables"], "correct": 2, "explanation": "The scope management plan explains how scope will be defined, developed, validated, and controlled. It is a management approach, not the detailed scope itself.", "type": "mcq"}, {"id": "M063", "chapter": 5, "topic": "Collecting requirements", "section": "Collecting Requirements", "stem": "A team asks only the sponsor what users need and proceeds directly to coding. Later, accessibility and operating requirements emerge from groups who were never consulted. The manager wants to reduce this risk in the next project. Which approach most directly improves requirements collection before scope is defined in detail?", "options": ["Ask developers to infer every requirement without user involvement.", "Delay user consultation until final acceptance testing.", "Engage relevant stakeholders using suitable elicitation techniques.", "Treat the sponsor's initial idea as a complete specification."], "correct": 2, "explanation": "Requirements collection should involve relevant stakeholders and appropriate techniques such as interviews, workshops, observation, and prototypes. One person's view may omit important needs.", "type": "mcq"}, {"id": "M064", "chapter": 5, "topic": "Traceability matrix", "section": "Collecting Requirements", "stem": "A regulator asks where a required audit function originated, which deliverable implements it, and how it will be tested. The team has requirements, code plans, and test cases, but the links are unclear. Which document most directly connects requirements with their origins and subsequent implementation and verification work?", "options": ["Cost performance report", "Responsibility assignment matrix", "Project organization chart", "Requirements traceability matrix"], "correct": 3, "explanation": "A requirements traceability matrix links requirements to their sources and related deliverables or verification. A responsibility matrix instead maps work to people or roles.", "type": "mcq"}, {"id": "M065", "chapter": 5, "topic": "Defining scope", "section": "Defining Scope", "stem": "The sponsor approves a document describing deliverables, acceptance criteria, exclusions, constraints, and assumptions. It explicitly states that the new portal will not replace payroll processing. This detail will help prevent future misunderstandings about boundaries. Which document is the team most directly developing in the scope-definition process described here?", "options": ["Project scope statement", "Project charter only", "Activity duration estimate", "Risk probability matrix"], "correct": 0, "explanation": "The scope statement describes detailed scope and boundaries, including exclusions and acceptance criteria. A charter is typically higher level and is created for authorization.", "type": "mcq"}, {"id": "M066", "chapter": 5, "topic": "Work breakdown structure", "section": "Creating the Work Breakdown Structure", "stem": "A manager groups the total project work around deliverables, then decomposes each major deliverable into smaller manageable components. The result is hierarchical and does not yet specify the sequence of every task. Which artifact is being created to establish a basis for later scheduling, estimating, and responsibility assignments?", "options": ["Stakeholder engagement matrix", "Precedence network diagram", "Work breakdown structure", "Resource calendar"], "correct": 2, "explanation": "A WBS is a deliverable-oriented decomposition of total project work. A network diagram represents activity dependencies, which is a different scheduling purpose.", "type": "mcq"}, {"id": "M067", "chapter": 5, "topic": "100 percent rule", "section": "Creating the Work Breakdown Structure", "stem": "A WBS for a software project includes development and testing but omits training and project management even though both are required. The manager argues that the WBS should show only visible product features. Which correction best reflects the need for the WBS to represent the project's total approved work?", "options": ["Exclude supporting work because it produces no software feature.", "Include all required project work, including supporting and management work.", "Use only work performed by external suppliers.", "Add every feature users might eventually request."], "correct": 1, "explanation": "The WBS should cover all approved project work, not just coded features. It should not include unapproved extras; completeness is defined by the authorized scope.", "type": "mcq"}, {"id": "M068", "chapter": 5, "topic": "Work package", "section": "Creating the Work Breakdown Structure", "stem": "A project team decomposes a deliverable until it reaches a manageable component that can be estimated and assigned. This component is the lowest level in the WBS the team will use for control. What term describes it, even though detailed schedule activities may still be derived from it later?", "options": ["Phase gate", "Work package", "Project portfolio", "Milestone"], "correct": 1, "explanation": "A work package is the lowest WBS level used for planning and control. A milestone is a significant event, and a work package can be broken into schedule activities.", "type": "mcq"}, {"id": "M069", "chapter": 5, "topic": "WBS dictionary", "section": "Creating the Work Breakdown Structure", "stem": "Two team leads interpret a short WBS label differently. One expects data conversion only; the other includes data cleansing and validation. The manager wants supporting detail about the component's work and boundaries without making the WBS graphic unreadable. Which artifact should provide this explanatory detail for the WBS item?", "options": ["Stakeholder register", "Project funding schedule", "Burndown chart", "WBS dictionary"], "correct": 3, "explanation": "The WBS dictionary adds detailed descriptions and information for WBS components. The graphic hierarchy alone may not adequately communicate the meaning of short labels.", "type": "mcq"}, {"id": "M070", "chapter": 5, "topic": "Scope baseline", "section": "Creating the Work Breakdown Structure", "stem": "After approval, the manager needs a reference for comparing actual scope performance and evaluating requested scope changes. A teammate proposes using only the activity calendar. Which combination forms the scope baseline in the textbook's scope-management discussion and therefore provides the appropriate approved scope reference for the project?", "options": ["Project charter, supplier invoice, and status report", "Scope statement, WBS, and WBS dictionary", "Activity list, resource calendar, and daily task board", "Risk register, issue log, and lessons learned"], "correct": 1, "explanation": "The scope baseline consists of the approved scope statement, WBS, and WBS dictionary. Schedule documents are related but do not replace the scope baseline.", "type": "mcq"}, {"id": "M071", "chapter": 5, "topic": "Validate scope vs. control quality", "section": "Validating Scope", "stem": "Quality staff inspect a deliverable and confirm that it meets technical requirements. The customer then reviews it and formally accepts it. A new manager uses the same process name for both events. Which distinction correctly identifies the customer's formal acceptance step, compared with the technical inspection performed beforehand?", "options": ["Customer acceptance is procurement planning; inspection is project selection.", "Customer acceptance is scope validation; technical checking is quality control.", "Both are scope collection because requirements are being invented.", "Customer acceptance is quality planning; technical checking is scope definition."], "correct": 1, "explanation": "Scope validation obtains formal acceptance of completed deliverables. Quality control checks correctness and compliance; a technically verified deliverable still needs the appropriate acceptance process.", "type": "mcq"}, {"id": "M072", "chapter": 5, "topic": "Scope creep", "section": "Controlling Scope", "stem": "Developers repeatedly add small enhancements requested in hallway conversations. Nobody evaluates their combined impact or updates approved scope through change control. The additions eventually consume the testing budget. Which concept best describes this pattern, even though each individual request appeared minor and was intended to please a user?", "options": ["Authorized baseline revision", "Scope creep", "Progressive elaboration within approved boundaries", "Formal scope validation"], "correct": 1, "explanation": "Scope creep is uncontrolled expansion of scope. Small, helpful-looking additions still need evaluation and authorization; their cumulative effect can be substantial.", "type": "mcq"}, {"id": "M073", "chapter": 5, "topic": "Gold plating", "section": "Controlling Scope", "stem": "Without a customer request or approved change, a developer adds an elaborate animation to impress the sponsor. It consumes time and complicates testing, although the original requirements never called for it. Which response best protects scope discipline while recognizing that an attractive addition is not automatically justified project work?", "options": ["Accept any extra feature if the developer believes users will like it.", "Automatically extend the deadline without documenting the change.", "Treat every extra feature as mandatory quality improvement.", "Do the approved work and route proposed extras through change control."], "correct": 3, "explanation": "Unrequested extras, often called gold plating, are not automatically beneficial. Project scope concerns required and approved work; extras may add risk and cost without agreed value.", "type": "mcq"}, {"id": "M074", "chapter": 5, "topic": "Prototyping", "section": "Collecting Requirements", "stem": "Users struggle to explain how they want a new scheduling screen to behave. The team builds a simple model, lets users interact with it, and uses their feedback to clarify requirements before full development. Which technique is most directly being used to reduce misunderstanding during requirements collection in this situation?", "options": ["Crashing", "Contract closure", "Prototyping", "Earned value analysis"], "correct": 2, "explanation": "A prototype makes ideas tangible so users can provide more useful feedback. It supports requirements discovery; it is not a schedule-compression or cost-performance technique.", "type": "mcq"}, {"id": "M075", "chapter": 5, "topic": "WBS approaches", "section": "Creating the Work Breakdown Structure", "stem": "A team begins by identifying specific pieces of work, clusters them into larger groups, and combines those groups into major deliverables. It does not start with the broad deliverables and progressively split them. Which approach to building a WBS most closely matches this direction of organization from detail toward the whole?", "options": ["Payback analysis", "Bottom-up approach", "Top-down approach", "Critical path method"], "correct": 1, "explanation": "Bottom-up construction starts with detailed work and organizes it upward. Top-down starts at the whole project or major deliverables and decomposes downward.", "type": "mcq"}, {"id": "M076", "chapter": 6, "topic": "Duration vs. effort", "section": "Estimating Activity Durations", "stem": "An activity requires 16 person-hours of effort. One analyst can devote four hours each working day to it, and no other constraints apply. The manager must place the activity on a calendar rather than report total labor. What is the expected duration in working days under these assumptions?", "options": ["64 working days", "16 working days", "4 working days", "2 working days"], "correct": 2, "explanation": "Duration = 16 person-hours / 4 hours per day = 4 working days. Effort is the amount of work; duration is the elapsed working time needed with the assigned availability.", "type": "mcq"}, {"id": "M077", "chapter": 6, "topic": "Milestones", "section": "Defining Activities", "stem": "A project schedule includes the event 'customer approves the design.' The design work itself is already represented by several activities. The manager wants this approval shown as a significant point in time rather than as another block of effort. How should this event normally be represented in the schedule?", "options": ["As a task with duration equal to the whole design phase", "As a milestone with zero duration", "As a work package that must last one week", "As a resource assigned full time"], "correct": 1, "explanation": "A milestone is a significant event and normally has zero duration. The work required to reach it is represented by the preceding activities.", "type": "mcq"}, {"id": "M078", "chapter": 6, "topic": "Mandatory dependency", "section": "Sequencing Activities", "stem": "A team cannot run a hardware installation test until the hardware has actually been installed. The ordering follows the physical nature of the work, not merely the team's preference or a supplier's external calendar. Which dependency category best describes this relationship when the project manager sequences these activities?", "options": ["External dependency solely because hardware is involved", "Discretionary dependency", "A dependency that must be removed in agile projects", "Mandatory dependency"], "correct": 3, "explanation": "Mandatory dependencies are inherent in the nature of the work. Discretionary dependencies reflect a chosen approach; external dependencies involve activities outside the project's control.", "type": "mcq"}, {"id": "M079", "chapter": 6, "topic": "Discretionary dependency", "section": "Sequencing Activities", "stem": "An experienced team prefers to finish all interface design before beginning any coding, although some coding could technically start earlier. The sequence comes from its customary approach rather than a physical necessity. Which dependency category is most appropriate, and thus worth reconsidering if schedule compression becomes necessary later?", "options": ["Mandatory dependency", "Discretionary dependency", "A finish-to-finish relationship by definition", "External dependency"], "correct": 1, "explanation": "Discretionary dependencies reflect preferred practices or team choices. They may offer flexibility for compression; the reason for a dependency differs from its relationship type.", "type": "mcq"}, {"id": "M080", "chapter": 6, "topic": "External dependency", "section": "Sequencing Activities", "stem": "A project can deploy a connection only after a telecommunications provider completes work managed outside the project. The team's internal tasks are ready, but it cannot directly schedule the provider's separate work. Which dependency category best identifies this reliance on an activity beyond the project's own control in this scenario?", "options": ["External dependency", "An internal dependency with no outside influence", "A resource-free milestone unrelated to scheduling", "Discretionary dependency only"], "correct": 0, "explanation": "An external dependency links project work to non-project activities. The reason is the outside work, not whether the dependency happens to be technically necessary as well.", "type": "mcq"}, {"id": "M081", "chapter": 6, "topic": "Finish-to-start", "section": "Sequencing Activities", "stem": "A testing activity is allowed to begin only after its predecessor's installation activity finishes. The manager represents the relationship in a precedence diagram. No overlap or waiting period has been specified. Which relationship type describes the condition linking the predecessor's completion to the successor's permitted start in this case?", "options": ["Finish-to-start", "Start-to-start", "Start-to-finish", "Finish-to-finish"], "correct": 0, "explanation": "Finish-to-start means the successor cannot start until the predecessor finishes. The other relationship types constrain different combinations of start and finish events.", "type": "mcq"}, {"id": "M082", "chapter": 6, "topic": "Lag", "section": "Sequencing Activities", "stem": "A migration activity finishes on Monday, but verification must wait two full working days for scheduled data feeds to settle before it can start. This waiting interval contains no verification work. Which scheduling concept most directly represents the required delay between predecessor completion and successor start, assuming a finish-to-start relationship?", "options": ["A two-day lead", "A two-day reduction in predecessor effort", "Two days of free float by definition", "A two-day lag"], "correct": 3, "explanation": "A lag adds a waiting interval to a dependency. A lead allows overlap; float describes allowable delay without affecting a successor or completion constraint, not mandatory waiting.", "type": "mcq"}, {"id": "M083", "chapter": 6, "topic": "Lead", "section": "Sequencing Activities", "stem": "The team can begin drafting training material two days before the software documentation is fully complete. The manager models this permitted overlap on a finish-to-start dependency instead of requiring the successor to wait until completion. Which concept describes the two-day advancement of the successor relative to the normal dependency?", "options": ["A two-day lead", "A mandatory two-day milestone", "A two-day project buffer", "A two-day lag"], "correct": 0, "explanation": "A lead advances the successor and permits overlap, often represented as negative lag. A lag delays a successor, which is the opposite effect.", "type": "mcq"}, {"id": "M084", "chapter": 6, "topic": "Critical path calculation", "section": "Critical Path Method", "stem": "A project has two independent paths that merge at completion. Path A–B–D takes 3 + 5 + 2 days. Path C–E takes 4 + 4 days. Assume no resource limits, leads, lags, or other constraints. Which statement correctly identifies the controlling path and earliest project completion time for this network?", "options": ["A–B–D is critical; completion requires 10 days.", "C–E is critical; completion requires 8 days.", "Both paths are critical; completion requires 18 days.", "A–B–D is critical; completion requires 5 days."], "correct": 0, "explanation": "The critical path is the longest duration path: 10 days versus 8. Parallel paths are not added together; the longest controls completion under these assumptions.", "type": "mcq"}, {"id": "M085", "chapter": 6, "topic": "Total float", "section": "Critical Path Method", "stem": "An activity has an early start of day 4 and a late start of day 7 in the same schedule, with no unusual calendar conventions. The manager wants to know how much it can be delayed without delaying the project finish under the current network. What is the activity's total float?", "options": ["7 days", "11 days", "3 days", "4 days"], "correct": 2, "explanation": "Total float = late start - early start = 7 - 4 = 3 days. It can also be calculated from late finish minus early finish.", "type": "mcq"}, {"id": "M086", "chapter": 6, "topic": "Changing critical paths", "section": "Critical Path Method", "stem": "A network has a 12-day critical path and another path lasting 11 days. Work on the second path slips by three days, with no corrective action and no shared activities between the paths. What happens to the controlling path and project duration when the revised network is assessed under these assumptions?", "options": ["The second path becomes critical and the project lasts 14 days.", "The project lasts 15 days because all three days are added to 12.", "The first path remains critical forever once identified.", "The project remains 12 days because the delayed work was originally noncritical."], "correct": 0, "explanation": "The second path becomes 11 + 3 = 14 days and overtakes the original 12-day path. Critical paths can change, so noncritical work must still be monitored.", "type": "mcq"}, {"id": "M087", "chapter": 6, "topic": "Crashing", "section": "Shortening a Project Schedule", "stem": "To shorten a project, the manager pays for additional specialist help on an activity that currently controls the finish date. The team assesses the extra cost per day saved and the feasibility of the resource addition. Which schedule-compression technique best describes this effort to reduce duration through added resources?", "options": ["Resource leveling", "Crashing", "Scope validation", "Fast tracking"], "correct": 1, "explanation": "Crashing adds resources or cost to shorten activities, focusing on work that can reduce the project duration. Fast tracking instead overlaps work that was sequential.", "type": "mcq"}, {"id": "M088", "chapter": 6, "topic": "Fast tracking", "section": "Shortening a Project Schedule", "stem": "A project manager allows integration testing to start on completed modules while other modules are still being built. These activities were previously planned in sequence. The decision could shorten delivery but introduces coordination and rework risk. Which compression technique most directly describes this intentional overlap of originally sequential activities?", "options": ["Crashing", "Cost aggregation", "Fast tracking", "Bottom-up estimating"], "correct": 2, "explanation": "Fast tracking overlaps work that would normally be sequential. It can increase rework and risk; crashing instead tries to shorten work by adding resources or cost.", "type": "mcq"}, {"id": "M089", "chapter": 6, "topic": "PERT calculation", "section": "Program Evaluation and Review Technique (PERT)", "stem": "A difficult interface task has an optimistic estimate of 4 days, a most likely estimate of 7 days, and a pessimistic estimate of 16 days. The manager uses the textbook's PERT weighted-average formula instead of a simple three-point average. What expected duration should be used for the activity?", "options": ["8 days", "9 days", "12 days", "7 days"], "correct": 0, "explanation": "PERT expected duration = (4 + 4×7 + 16)/6 = 48/6 = 8 days. The simple average is 9, but PERT weights the most likely estimate four times.", "type": "mcq"}, {"id": "M090", "chapter": 6, "topic": "Critical chain", "section": "Critical Chain Scheduling", "stem": "A team finds that two activities compete for the same specialist, even though a basic network suggests they could run in parallel. Management also wants shared buffers instead of hidden safety time in every estimate. Which scheduling approach explicitly considers resource constraints and buffers alongside dependency logic in this situation?", "options": ["Scope validation", "Critical chain scheduling", "A WBS dictionary alone", "Simple payback analysis"], "correct": 1, "explanation": "Critical chain applies constraints thinking, accounts for resource limitations, and uses buffers. Dependency-only critical path reasoning can miss resource conflicts.", "type": "mcq"}, {"id": "M091", "chapter": 7, "topic": "Sunk costs", "section": "Basic Principles of Cost Management", "stem": "A cancelled platform has already consumed $300,000 that cannot be recovered. Continuing would cost more than the expected future benefit. Which treatment of the past spending best supports the decision?", "options": ["Treat the past spending as a new benefit.", "Count sunk costs as future revenue.", "Continue solely to recover the historical spending.", "Exclude sunk costs from the forward-looking comparison."], "correct": 3, "explanation": "Sunk costs have already been incurred and cannot be changed by the decision. Compare relevant future costs and benefits rather than continuing to justify past spending.", "type": "mcq"}, {"id": "M092", "chapter": 7, "topic": "Life cycle costing", "section": "Basic Principles of Cost Management", "stem": "System A is cheaper to buy but expensive to operate. System B costs more initially but uses fewer support resources. Which evaluation best avoids choosing solely on purchase price?", "options": ["Ignore maintenance costs because delivery ends at launch.", "Compare total ownership costs across the systems' life cycles.", "Select whichever has the lowest acquisition price.", "Treat all recurring costs as sunk costs before purchase."], "correct": 1, "explanation": "Life cycle costing considers acquisition and later operating and support costs. Costs not yet incurred are not sunk merely because they recur.", "type": "mcq"}, {"id": "M093", "chapter": 7, "topic": "Analogous estimates", "section": "Tools and Techniques for Cost Estimation", "stem": "A manager has little detail about a proposed application and estimates its cost using a similar completed project, adjusted for known differences. Which estimating technique is being applied?", "options": ["Earned value measurement", "Bottom-up estimating", "Analogous estimating", "Reserve analysis only"], "correct": 2, "explanation": "Analogous estimates use comparable prior work. Bottom-up estimating sums detailed components, which are not yet available in this scenario.", "type": "mcq"}, {"id": "M094", "chapter": 7, "topic": "Bottom-up estimates", "section": "Tools and Techniques for Cost Estimation", "stem": "Team leads estimate each detailed work component and the manager aggregates those estimates into a project total. Which cost-estimating approach most directly describes this procedure?", "options": ["Simple payback analysis", "Bottom-up estimating", "Analogous estimating", "Top-down allocation without detail"], "correct": 1, "explanation": "Bottom-up estimates build a total from individual components. They can be detailed but take effort and depend on the quality of underlying work estimates.", "type": "mcq"}, {"id": "M095", "chapter": 7, "topic": "Parametric estimates", "section": "Tools and Techniques for Cost Estimation", "stem": "Historical data suggests that configuring one standard workstation costs $80. A team uses this rate to estimate 250 comparable configurations. What method and total are appropriate?", "options": ["Parametric estimating; $20,000", "Earned value analysis; $20,000", "Analogous estimating; $3,125", "Bottom-up estimating; $330"], "correct": 0, "explanation": "Parametric estimating applies a rate or model to quantities: 250 × $80 = $20,000. The rate must be suitable for the work being estimated.", "type": "mcq"}, {"id": "M096", "chapter": 7, "topic": "Cost baseline", "section": "Determining the Budget", "stem": "A sponsor has approved a total budget but wants planned expenditure by period for later comparison with performance. Which output provides this time-phased reference for project cost control?", "options": ["Cost baseline", "Product backlog", "Stakeholder register", "Issue log"], "correct": 0, "explanation": "The cost baseline distributes approved budget over time. A total alone does not show when expenditure or value is planned.", "type": "mcq"}, {"id": "M097", "chapter": 7, "topic": "Earned value", "section": "Earned Value Management", "stem": "A work package has a budget of $40,000 and is assessed as 25% complete. Actual spending is $15,000. Using budgeted value of work performed, what is its earned value?", "options": ["$10,000", "$40,000", "$15,000", "$25,000"], "correct": 0, "explanation": "EV is the budgeted value of completed work: .25 × $40,000 = $10,000. Actual spending is AC and does not determine the amount of value earned.", "type": "mcq"}, {"id": "M098", "chapter": 7, "topic": "Cost variance", "section": "Earned Value Management", "stem": "At a status date, EV is $60,000 and AC is $75,000. The manager wants to know whether completed work cost more than its budgeted value. What is CV and its interpretation?", "options": ["-$15,000; ahead of schedule", "+$135,000; over budget", "+$15,000; under budget", "-$15,000; over budget for work performed"], "correct": 3, "explanation": "CV = EV - AC = -$15,000. A negative cost variance indicates cost overrun relative to the budgeted value of completed work, not a schedule condition.", "type": "mcq"}, {"id": "M099", "chapter": 7, "topic": "Schedule variance", "section": "Earned Value Management", "stem": "At the same status date, EV is $60,000 and PV is $80,000. What does the EVM schedule variance indicate, without treating its monetary units as a direct count of calendar days?", "options": ["SV cannot be calculated without actual costs.", "SV is -$20,000; less work is complete than planned.", "SV is -20 days; the finish date is exactly 20 days late.", "SV is +$20,000; more work is complete than planned."], "correct": 1, "explanation": "SV = EV - PV = -$20,000. It expresses a value-based schedule shortfall; it does not directly report the number of days the project is late.", "type": "mcq"}, {"id": "M100", "chapter": 7, "topic": "Cost performance index", "section": "Earned Value Management", "stem": "A team has earned $48,000 of budgeted work while spending $60,000. Which CPI and interpretation should the manager report when evaluating cost efficiency at this status date?", "options": ["1.25; $1.25 of budgeted work per dollar spent", "0.80; $0.80 of budgeted work per dollar spent", "1.25; the project must be ahead of schedule", "0.80; 80% of the entire project is complete"], "correct": 1, "explanation": "CPI = EV/AC = 48,000/60,000 = .80. This measures cost efficiency, not overall percentage complete or schedule status.", "type": "mcq"}, {"id": "M101", "chapter": 7, "topic": "Schedule performance index", "section": "Earned Value Management", "stem": "A project has EV of $90,000, PV of $100,000, and AC of $85,000. Which SPI correctly measures progress against planned work, independently of cost efficiency?", "options": ["0.90", "1.11", "1.06", "0.85"], "correct": 0, "explanation": "SPI = EV/PV = .90, indicating less earned work than planned. EV/AC would calculate CPI, a different indicator.", "type": "mcq"}, {"id": "M102", "chapter": 7, "topic": "Estimate at completion", "section": "Earned Value Management", "stem": "BAC is $200,000 and CPI is 0.80. Assume current cost efficiency will persist for the remaining work. Using EAC = BAC/CPI, what total cost forecast follows?", "options": ["$200,000", "$250,000", "$40,000", "$160,000"], "correct": 1, "explanation": "EAC = 200,000/.80 = $250,000. The formula depends on the stated assumption that current cost efficiency continues; it is not universally appropriate.", "type": "mcq"}, {"id": "M103", "chapter": 7, "topic": "Contingency vs. management reserves", "section": "Basic Principles of Cost Management", "stem": "A manager distinguishes a budget allowance for identified risks from money held for unforeseen work within scope. Which reserve is associated with identified risks and is generally included in the cost baseline?", "options": ["Sunk-cost reserve", "Management reserve", "Contingency reserve", "Profit margin"], "correct": 2, "explanation": "Contingency reserves address identified risks or known unknowns and are generally included in the baseline. Management reserves address unknown unknowns and are outside the cost baseline.", "type": "mcq"}, {"id": "M104", "chapter": 8, "topic": "Quality vs. grade", "section": "What Is Project Quality Management?", "stem": "A basic application has few features but reliably meets every agreed requirement. A premium application has many features but fails frequently. Which conclusion best separates quality from grade?", "options": ["Lower-grade products must have unacceptable quality.", "The basic application can have high quality despite its lower grade.", "More features automatically mean higher quality.", "Quality depends only on the number of features."], "correct": 1, "explanation": "Quality concerns meeting requirements and fitness for use. Grade relates to category or feature level; a simple product can be reliable and fully fit for its purpose.", "type": "mcq"}, {"id": "M105", "chapter": 8, "topic": "Plan quality", "section": "Planning Quality Management", "stem": "Before testing starts, a team agrees response-time targets, defect thresholds, and how compliance will be demonstrated. Which quality-management activity is most directly represented by these decisions?", "options": ["Controlling quality after delivery", "Validating scope only", "Planning quality management", "Closing procurement"], "correct": 2, "explanation": "Planning quality identifies relevant standards and how to satisfy them. Measuring completed results against those standards comes later in control quality.", "type": "mcq"}, {"id": "M106", "chapter": 8, "topic": "Manage quality", "section": "Managing Quality", "stem": "An audit finds that teams skip an agreed peer-review process. The manager improves the development process to prevent defects, rather than merely retesting the latest build. Which focus best describes this action?", "options": ["Reducing product scope without approval", "Measuring only the latest product's defects", "Accepting finished deliverables from the customer", "Managing quality through process improvement"], "correct": 3, "explanation": "Managing quality translates quality plans into activities and improves processes. Control quality is more directly concerned with checking particular outputs.", "type": "mcq"}, {"id": "M107", "chapter": 8, "topic": "Control quality", "section": "Controlling Quality", "stem": "Testers run the completed module against specified performance criteria, record defects, and verify corrections. Which quality-management process most directly checks these particular work results?", "options": ["Developing the project charter", "Planning scope management", "Controlling quality", "Strategic project selection"], "correct": 2, "explanation": "Control quality monitors specific results for compliance with standards. It differs from setting the standards or improving the underlying processes.", "type": "mcq"}, {"id": "M108", "chapter": 8, "topic": "Pareto chart", "section": "Tools and Techniques for Quality Control", "stem": "A help desk categorizes incidents and finds a few causes account for most complaints. Which chart best helps prioritize these categories from the largest contributor downward?", "options": ["Scatter diagram", "Project network diagram", "Pareto chart", "Resource histogram only"], "correct": 2, "explanation": "A Pareto chart orders categories by frequency or impact to highlight the vital few contributors. A scatter diagram explores relationships between variables.", "type": "mcq"}, {"id": "M109", "chapter": 8, "topic": "Cause-and-effect diagram", "section": "Tools and Techniques for Quality Control", "stem": "A team explores why deployments fail by grouping potential causes under people, methods, tools, and environment. Which quality tool is best suited to organizing these possible root causes?", "options": ["Cost baseline", "Gantt chart", "Cause-and-effect diagram", "Stakeholder register"], "correct": 2, "explanation": "A cause-and-effect or fishbone diagram organizes possible causes of a problem. It supports root-cause exploration, rather than plotting activities over time.", "type": "mcq"}, {"id": "M110", "chapter": 8, "topic": "Control charts", "section": "Tools and Techniques for Quality Control", "stem": "A team records process performance in time order and compares it with calculated upper and lower control limits to identify unusual variation. Which tool serves this purpose?", "options": ["Pareto chart", "WBS dictionary", "Control chart", "Responsibility matrix"], "correct": 2, "explanation": "Control charts track process variation over time and help distinguish stable behavior from special causes. Control limits are not simply the customer's specification limits.", "type": "mcq"}, {"id": "M111", "chapter": 8, "topic": "Scatter diagrams", "section": "Tools and Techniques for Quality Control", "stem": "Analysts want to examine whether larger code changes tend to coincide with more defects. They plot paired observations of change size and defect count. Which tool is being used?", "options": ["Flowchart", "Checksheet only", "Milestone chart", "Scatter diagram"], "correct": 3, "explanation": "A scatter diagram explores a possible relationship between two variables. An observed association alone does not prove a causal relationship.", "type": "mcq"}, {"id": "M112", "chapter": 8, "topic": "Six Sigma", "section": "Six Sigma", "stem": "A team adopts a structured improvement method to reduce variation and defects in an existing support process. Which sequence correctly expands the DMAIC improvement cycle used in Six Sigma?", "options": ["Develop, manage, approve, inspect, close", "Define, measure, analyze, improve, control", "Design, measure, accept, implement, certify", "Define, monitor, authorize, integrate, close"], "correct": 1, "explanation": "DMAIC means define, measure, analyze, improve, and control. It is a process-improvement cycle, not the five project management process groups.", "type": "mcq"}, {"id": "M113", "chapter": 8, "topic": "Prevention costs", "section": "The Cost of Quality", "stem": "A company pays for training and improved development practices to prevent defects before they occur. How should these expenditures be classified within the cost of quality?", "options": ["Internal failure costs", "Prevention costs", "External failure costs", "Sunk benefits"], "correct": 1, "explanation": "Prevention costs aim to avoid defects. Appraisal costs evaluate quality; failure costs arise from defects discovered before or after delivery.", "type": "mcq"}, {"id": "M114", "chapter": 8, "topic": "Appraisal costs", "section": "The Cost of Quality", "stem": "A team spends money on inspections and testing to determine whether outputs meet requirements. Which cost-of-quality category best describes these evaluation activities, assuming no rework is included?", "options": ["Appraisal costs", "External failure costs", "Warranty costs only", "Prevention costs"], "correct": 0, "explanation": "Appraisal costs cover evaluating conformance, such as inspection and testing. Rework and customer warranty claims belong to failure-related categories.", "type": "mcq"}, {"id": "M115", "chapter": 8, "topic": "Failure costs", "section": "The Cost of Quality", "stem": "A defect is found and corrected before shipment; a different defect produces warranty claims after delivery. How should the two costs be classified, respectively?", "options": ["Appraisal and prevention", "Prevention and appraisal", "External failure and prevention", "Internal failure and external failure"], "correct": 3, "explanation": "Internal failure costs arise from defects before delivery. External failure costs arise after delivery, such as warranty work and customer-related consequences.", "type": "mcq"}, {"id": "M116", "chapter": 8, "topic": "Testing levels", "section": "Testing", "stem": "A single component passes its own tests, but problems appear when it exchanges data with another component. Which testing level most directly targets the interaction now failing?", "options": ["Integration testing", "Unit testing only", "Cost-baseline validation", "Project portfolio review"], "correct": 0, "explanation": "Integration testing examines combined components and their interfaces. Unit testing focuses on individual components; passing it does not guarantee correct interactions.", "type": "mcq"}, {"id": "M117", "chapter": 9, "topic": "Herzberg", "section": "Keys to Managing and Leading People", "stem": "A company improves salaries and office conditions, reducing complaints, yet employees still lack enthusiasm for their work. According to Herzberg, which additional factor is more directly a motivator?", "options": ["Basic workplace conditions alone", "Removing all challenging assignments", "Achievement and meaningful responsibility", "Administrative policies alone"], "correct": 2, "explanation": "Herzberg distinguishes hygiene factors, which reduce dissatisfaction, from motivators such as achievement, responsibility, recognition, and growth.", "type": "mcq"}, {"id": "M118", "chapter": 9, "topic": "Maslow", "section": "Keys to Managing and Leading People", "stem": "A manager uses Maslow's hierarchy to consider an employee's desire for achievement, recognition, and respect. Which need level is most directly associated with these concerns?", "options": ["Safety", "Basic survival", "Esteem", "Physiological"], "correct": 2, "explanation": "Esteem concerns recognition, respect, and achievement. Physiological and safety needs concern more basic conditions; self-actualization involves realizing one's potential.", "type": "mcq"}, {"id": "M119", "chapter": 9, "topic": "McClelland", "section": "Keys to Managing and Leading People", "stem": "A team member enjoys challenging but achievable goals and wants clear feedback on personal results. Which acquired need in McClelland's theory is most directly evident?", "options": ["Need for hygiene", "Need for affiliation only", "Need for security", "Need for achievement"], "correct": 3, "explanation": "McClelland identifies achievement, affiliation, and power as acquired needs. Challenging goals and performance feedback particularly fit achievement.", "type": "mcq"}, {"id": "M120", "chapter": 9, "topic": "Theory X", "section": "Keys to Managing and Leading People", "stem": "A supervisor assumes workers inherently dislike work and must be closely controlled or threatened to perform. Which management assumption does this illustrate in McGregor's theory?", "options": ["Theory Z", "Theory Y", "Self-actualization", "Theory X"], "correct": 3, "explanation": "Theory X assumes people dislike work and need control. Theory Y assumes people can exercise self-direction and find work natural under appropriate conditions.", "type": "mcq"}, {"id": "M121", "chapter": 9, "topic": "Theory Y", "section": "Keys to Managing and Leading People", "stem": "A manager gives a capable team meaningful responsibility, believing that committed people can direct themselves and seek responsibility. Which assumption is most consistent with this management approach?", "options": ["Hygiene theory as a reporting structure", "Theory X", "Theory Y", "Coercion as the only source of effort"], "correct": 2, "explanation": "Theory Y supports self-direction and responsibility under suitable conditions. It does not mean that goals, coordination, or management become unnecessary.", "type": "mcq"}, {"id": "M122", "chapter": 9, "topic": "Expert power", "section": "Keys to Managing and Leading People", "stem": "Developers follow an architect's advice because they respect her deep technical knowledge, although she has no formal authority over their employment. What is the main power base here?", "options": ["Reward power", "Coercive power", "Legitimate power", "Expert power"], "correct": 3, "explanation": "Expert power comes from knowledge or skill. Legitimate power comes from a formal position; coercive and reward power rely on penalties and benefits.", "type": "mcq"}, {"id": "M123", "chapter": 9, "topic": "Referent power", "section": "Keys to Managing and Leading People", "stem": "A team follows a coordinator because members admire and identify with him. He controls neither salaries nor formal job assignments. Which power base best describes this influence?", "options": ["Referent power", "Coercive power", "Legitimate power", "Reward power"], "correct": 0, "explanation": "Referent power arises from admiration and personal identification. The scenario does not establish authority, reward control, or the threat of punishment.", "type": "mcq"}, {"id": "M124", "chapter": 9, "topic": "RACI", "section": "Planning Resource Management", "stem": "A responsibility matrix distinguishes people doing the work from the person answerable for its successful completion. In RACI, which letter identifies that ultimate accountability for the specified activity?", "options": ["A", "C", "R", "I"], "correct": 0, "explanation": "A means accountable. R means responsible for performing work, C consulted, and I informed. The distinction helps clarify ownership versus contribution.", "type": "mcq"}, {"id": "M125", "chapter": 9, "topic": "Resource leveling", "section": "Resource Loading and Leveling", "stem": "One specialist is assigned to two full-time tasks on the same day. The manager adjusts task dates to resolve the over-allocation, accepting that the finish date may move. What technique is this?", "options": ["Fast tracking", "Resource leveling", "Scope validation", "Gold plating"], "correct": 1, "explanation": "Resource leveling resolves resource conflicts by adjusting the schedule and can extend project duration. Fast tracking overlaps activities and may worsen such a conflict.", "type": "mcq"}, {"id": "M126", "chapter": 9, "topic": "Team development", "section": "Developing the Project Team", "stem": "Team members start challenging one another's roles and working methods after an initially polite orientation. According to Tuckman's model, which stage most directly describes this conflict-prone period?", "options": ["Storming", "Adjourning", "Performing", "Forming"], "correct": 0, "explanation": "Storming involves conflict and adjustment. Forming is initial orientation; norming develops shared practices; performing is effective work; adjourning is separation.", "type": "mcq"}, {"id": "M127", "chapter": 9, "topic": "Conflict resolution", "section": "Managing the Project Team", "stem": "Two specialists disagree about an interface. The manager helps them examine the underlying needs and jointly develop a solution that satisfies both, rather than splitting the difference. Which approach is this?", "options": ["Collaborating or problem solving", "Withdrawing", "Forcing", "Smoothing only"], "correct": 0, "explanation": "Collaboration confronts the underlying problem to seek a mutually satisfactory solution. Compromise gives up something on both sides; smoothing downplays differences.", "type": "mcq"}, {"id": "M128", "chapter": 9, "topic": "Emotional intelligence", "section": "Keys to Managing and Leading People", "stem": "A manager notices personal frustration during a tense meeting, regulates the reaction, and recognizes anxiety in colleagues before responding constructively. Which capability is most directly demonstrated?", "options": ["Parametric estimating", "Critical path analysis", "Coercive authority", "Emotional intelligence"], "correct": 3, "explanation": "Emotional intelligence involves recognizing and managing one's own emotions and understanding others' emotions. It supports constructive leadership and interaction.", "type": "mcq"}, {"id": "M129", "chapter": 9, "topic": "Acquiring vs. developing", "section": "Acquiring Resources", "stem": "The project manager negotiates for a specialist to join the team. Later, that specialist attends training to improve collaboration and skills. Which pair of processes best describes these actions in order?", "options": ["Acquiring resources, then developing the team", "Developing the team, then identifying stakeholders", "Managing procurement, then validating scope", "Controlling scope, then closing the project"], "correct": 0, "explanation": "Acquiring resources obtains people or physical resources. Developing the team improves competencies, interaction, and team effectiveness after resources are available.", "type": "mcq"}, {"id": "M130", "chapter": 10, "topic": "Communication channels", "section": "Understanding Communication Channels", "stem": "A six-person team adds two members. Using n(n−1)/2 potential two-way communication channels, how many channels does the eight-person team have, and how many were added?", "options": ["56 total; 26 added", "28 total; 15 added", "28 total; 13 added", "16 total; 4 added"], "correct": 2, "explanation": "Eight people yield 8×7/2 = 28 channels. Six yielded 6×5/2 = 15, so 13 channels were added. The formula counts unordered pairs.", "type": "mcq"}, {"id": "M131", "chapter": 10, "topic": "Communications plan", "section": "Planning Communications Management", "stem": "Stakeholders complain that they receive either too much detail or updates too late. Which plan should specify information needs, recipients, methods, timing, and responsibility for distributing project information?", "options": ["Activity duration estimate", "Communications management plan", "Procurement statement of work", "Scope baseline"], "correct": 1, "explanation": "The communications plan establishes who needs what information, when, how, and from whom. It should be tailored to stakeholder needs.", "type": "mcq"}, {"id": "M132", "chapter": 10, "topic": "Interactive communication", "section": "Managing Communications", "stem": "Two teams must resolve a complex misunderstanding quickly through questions and immediate feedback. Which communication method best supports a shared understanding during the exchange?", "options": ["Posting a document without notifying anyone", "A one-way bulk newsletter", "Archiving a report for later retrieval", "Interactive discussion"], "correct": 3, "explanation": "Interactive communication permits immediate exchange and feedback. Push and pull methods can be useful but are less suited to resolving an urgent complex misunderstanding alone.", "type": "mcq"}, {"id": "M133", "chapter": 10, "topic": "Push communication", "section": "Managing Communications", "stem": "A manager emails a weekly status report directly to a defined distribution list. Recipients receive the message, but the manager cannot assume they understood it. What method is illustrated?", "options": ["Pull communication", "No communication unless everyone replies", "Interactive communication by definition", "Push communication"], "correct": 3, "explanation": "Push sends information to recipients. Delivery does not guarantee reading or understanding; a one-way email is not automatically an interactive exchange.", "type": "mcq"}, {"id": "M134", "chapter": 10, "topic": "Pull communication", "section": "Managing Communications", "stem": "A large project stores detailed reference materials in a portal so interested users can retrieve them when needed. Which communication method best describes this access model?", "options": ["Push communication", "Coercive communication", "Interactive conversation", "Pull communication"], "correct": 3, "explanation": "Pull communication makes information available for recipients to access. It is suitable for large bodies of information but requires users to know where and how to retrieve it.", "type": "mcq"}, {"id": "M135", "chapter": 10, "topic": "Audience needs", "section": "Keys to Good Communications", "stem": "An executive wants decisions and business impact, while developers need technical detail. What reporting approach best addresses both without assuming one identical document suits every audience?", "options": ["Avoid executive reports until all technical work is finished.", "Send the full technical log to everyone.", "Send only financial totals to every stakeholder.", "Tailor content and detail to each audience's needs."], "correct": 3, "explanation": "Effective communication considers individual and group needs. The same raw information may need different presentation and level of detail for different recipients.", "type": "mcq"}, {"id": "M136", "chapter": 10, "topic": "Bad news", "section": "Keys to Good Communications", "stem": "The team discovers a serious delay. The manager wants to preserve trust and enable a decision. Which approach best supports effective communication of this unwelcome development?", "options": ["Send only optimistic metrics unrelated to the delay.", "Hide the delay until there is no possible recovery.", "Wait for the sponsor to discover the issue independently.", "Communicate promptly with evidence, impacts, and options."], "correct": 3, "explanation": "Timely, accurate communication of bad news enables action. Concealment reduces trust and deprives stakeholders of opportunities to help resolve the problem.", "type": "mcq"}, {"id": "M137", "chapter": 10, "topic": "Active listening", "section": "Keys to Good Communications", "stem": "During a requirements discussion, the manager summarizes what the user said and asks whether the summary is accurate before proposing a solution. Which practice is most directly demonstrated?", "options": ["Resource crashing", "Scope acceptance", "One-way reporting", "Active listening and checking understanding"], "correct": 3, "explanation": "Paraphrasing and confirming meaning reduces misunderstanding. Listening is an active part of communication, not merely waiting to speak.", "type": "mcq"}, {"id": "M138", "chapter": 10, "topic": "Status vs. progress", "section": "Reporting Performance", "stem": "A report describes where the project stands today, while another describes work completed during the last fortnight. Which pair of report types best matches these purposes respectively?", "options": ["Progress report and forecast", "Status report and progress report", "Forecast and status report", "Risk register and business case"], "correct": 1, "explanation": "Status describes the position at a point in time. Progress describes accomplishments over a period; a forecast estimates future performance.", "type": "mcq"}, {"id": "M139", "chapter": 10, "topic": "Forecasts", "section": "Reporting Performance", "stem": "Using current trends, a manager predicts the likely completion date and total cost rather than merely reporting historical results. Which type of performance information is being produced?", "options": ["Requirements traceability matrix", "Stakeholder register", "Acceptance certificate", "Forecast"], "correct": 3, "explanation": "A forecast predicts future conditions or outcomes using available information. A status report instead describes the current position.", "type": "mcq"}, {"id": "M140", "chapter": 10, "topic": "Effective meetings", "section": "Suggestions for Improving Project Communications", "stem": "A weekly meeting runs long and produces no decisions or follow-up. Which change most directly improves its usefulness for participants and the project?", "options": ["Remove all time limits and avoid assigning action owners.", "Replace every discussion with an unstructured status monologue.", "Invite everyone regardless of relevance.", "Use a clear purpose, agenda, and recorded actions with owners."], "correct": 3, "explanation": "Effective meetings need a purpose, appropriate participants, structure, and follow-through. More attendance or more time does not by itself improve results.", "type": "mcq"}, {"id": "M141", "chapter": 10, "topic": "Monitoring communications", "section": "Controlling Communications", "stem": "Reports are distributed exactly as planned, but stakeholders still cannot make needed decisions. What should the manager do when assessing whether project communications are effective?", "options": ["Stop collecting feedback because the plan was approved.", "Treat distribution as proof that communication succeeded.", "Increase report length without investigating the problem.", "Check whether information needs are met and adapt the approach."], "correct": 3, "explanation": "Monitoring or controlling communications considers whether information flows effectively and meets needs. Sending information is an activity, not proof of understanding or usefulness.", "type": "mcq"}, {"id": "M142", "chapter": 10, "topic": "Lessons learned", "section": "Suggestions for Improving Project Communications", "stem": "A team wants future projects to benefit from both its successful practices and its mistakes. Which communication artifact best records these insights rather than merely listing current tasks?", "options": ["Daily attendance register", "Supplier invoice", "Lessons-learned report", "Activity resource calendar"], "correct": 2, "explanation": "Lessons learned capture experience that can improve future work. They should describe useful insights and context, not simply record who attended or which task was scheduled.", "type": "mcq"}, {"id": "M143", "chapter": 11, "topic": "Threats and opportunities", "section": "The Importance of Project Risk Management", "stem": "A supplier may deliver late, while a new automation technique might reduce testing time. Both are uncertain. How should the project manager treat them in risk management?", "options": ["Treat the opportunity as a guaranteed benefit.", "Track only the possible delay as a risk.", "Consider both the threat and the opportunity.", "Record both as issues that have already occurred."], "correct": 2, "explanation": "Risk includes uncertain events with negative or positive effects. A realized event is an issue; an opportunity remains uncertain until it occurs.", "type": "mcq"}, {"id": "M144", "chapter": 11, "topic": "Risk register", "section": "Identifying Risks", "stem": "The team records potential events, causes, owners, likelihood, impacts, and responses in a shared document that evolves during delivery. What artifact is this?", "options": ["WBS dictionary", "Risk register", "Supplier scorecard", "Scope statement"], "correct": 1, "explanation": "The risk register captures identified risks and related analysis and response information. It is updated throughout the project rather than fixed at initiation.", "type": "mcq"}, {"id": "M145", "chapter": 11, "topic": "Qualitative analysis", "section": "Performing Qualitative Risk Analysis", "stem": "A workshop rates risks as low, medium, or high using likelihood and impact categories, then prioritizes attention. Which analysis is most directly being performed?", "options": ["Earned value analysis", "Simple payback analysis", "Qualitative risk analysis", "Quantitative simulation"], "correct": 2, "explanation": "Qualitative analysis prioritizes risks using assessments such as probability and impact scales. Quantitative analysis models numerical effects on project objectives.", "type": "mcq"}, {"id": "M146", "chapter": 11, "topic": "Expected monetary value", "section": "Performing Quantitative Risk Analysis", "stem": "A risk has a 20% probability of causing a $50,000 loss. For a simple expected monetary value calculation with no other outcomes, what is the expected loss?", "options": ["$40,000", "$50,000", "$10,000", "$250,000"], "correct": 2, "explanation": "Expected loss = .20 × $50,000 = $10,000, or EMV of -$10,000 when losses use negative signs. It is an average expectation, not the certain realized loss.", "type": "mcq"}, {"id": "M147", "chapter": 11, "topic": "Monte Carlo simulation", "section": "Performing Quantitative Risk Analysis", "stem": "A manager uses probability distributions for uncertain durations and repeatedly simulates possible project outcomes to estimate the chance of finishing by a target date. Which technique is this?", "options": ["A stakeholder power grid", "A single deterministic schedule calculation", "A qualitative checklist only", "Monte Carlo simulation"], "correct": 3, "explanation": "Monte Carlo simulation samples uncertain inputs repeatedly to model possible outcomes. It can estimate probabilities of schedule or cost targets.", "type": "mcq"}, {"id": "M148", "chapter": 11, "topic": "Avoidance", "section": "Planning Risk Responses", "stem": "A project removes a risky experimental component from its approved approach and chooses a proven design, eliminating a specific threat associated with that component. Which response is most directly illustrated?", "options": ["Risk acceptance", "Risk transfer", "Risk exploitation", "Risk avoidance"], "correct": 3, "explanation": "Avoidance changes the approach to eliminate a threat. Mitigation reduces likelihood or impact while the threat remains; transfer shifts responsibility or consequences to another party.", "type": "mcq"}, {"id": "M149", "chapter": 11, "topic": "Mitigation", "section": "Planning Risk Responses", "stem": "The team adds compatibility tests early to lower the probability of an integration failure. It still uses the same technology and retains responsibility. Which threat response best describes this action?", "options": ["Risk transfer", "Risk acceptance without action", "Risk mitigation", "Risk exploitation"], "correct": 2, "explanation": "Mitigation reduces a threat's probability or impact. The risk has not been removed entirely or shifted to another party.", "type": "mcq"}, {"id": "M150", "chapter": 11, "topic": "Transfer", "section": "Planning Risk Responses", "stem": "An organization purchases insurance against a specified financial loss, shifting covered financial consequences to an insurer. Which risk response does this represent, without assuming the underlying event cannot happen?", "options": ["Risk avoidance", "Risk exploitation", "Risk enhancement", "Risk transference"], "correct": 3, "explanation": "Transfer shifts consequences and management responsibility through mechanisms such as insurance. It does not eliminate the event or every residual responsibility.", "type": "mcq"}, {"id": "M151", "chapter": 11, "topic": "Exploitation", "section": "Planning Risk Responses", "stem": "A rare opportunity could deliver an early release. The manager assigns the strongest available resources specifically to make the opportunity occur, rather than simply increasing its likelihood slightly. Which positive-risk response is intended?", "options": ["Exploitation", "Transference of a threat", "Mitigation", "Passive acceptance"], "correct": 0, "explanation": "Exploitation aims to ensure a positive opportunity is realized. Enhancement increases its probability or impact without necessarily trying to make it certain.", "type": "mcq"}, {"id": "M152", "chapter": 11, "topic": "Sharing", "section": "Planning Risk Responses", "stem": "A company forms a partnership with another firm that has the capabilities needed to capture a market opportunity. They agree to share benefits and responsibility. Which positive-risk strategy is illustrated?", "options": ["Sharing", "Threat mitigation only", "Coercion", "Avoidance"], "correct": 0, "explanation": "Sharing allocates opportunity ownership to a party or partnership best positioned to realize it. It is a positive-risk response, distinct from transferring a threat.", "type": "mcq"}, {"id": "M153", "chapter": 11, "topic": "Contingency vs. fallback", "section": "Planning Risk Responses", "stem": "A team prepares a response to use if an identified risk occurs, plus a backup response if that first response fails. What are the two plans called respectively?", "options": ["Contingency plan and fallback plan", "Risk register and resource histogram", "Baseline and scope statement", "Fallback plan and project charter"], "correct": 0, "explanation": "A contingency plan is activated for an identified event. A fallback plan is used if the initial response proves ineffective.", "type": "mcq"}, {"id": "M154", "chapter": 11, "topic": "Delphi technique", "section": "Identifying Risks", "stem": "Experts provide anonymous risk opinions through repeated questionnaires, with summarized feedback between rounds. The team wants to reduce dominance by a vocal participant. Which technique is being used?", "options": ["Open brainstorming only", "Pareto analysis", "Fast tracking", "Delphi technique"], "correct": 3, "explanation": "Delphi seeks expert input through structured, often anonymous rounds. Anonymity and feedback help reduce social pressure and individual dominance.", "type": "mcq"}, {"id": "M155", "chapter": 11, "topic": "Residual vs. secondary risk", "section": "Planning Risk Responses", "stem": "A mitigation leaves some of the original threat unresolved and also introduces a new dependency risk. What are these risks called respectively?", "options": ["Residual risk and secondary risk", "Issue and acceptance criterion", "Secondary risk and residual risk", "Opportunity and sunk cost"], "correct": 0, "explanation": "Residual risk remains after a response. Secondary risk is newly created by implementing the response; both need appropriate attention.", "type": "mcq"}, {"id": "M156", "chapter": 12, "topic": "Make-or-buy analysis", "section": "Planning Procurement Management", "stem": "An organization compares building an integration tool internally with purchasing an outside service, considering costs and capability. What analysis is most directly being performed before deciding how to obtain the result?", "options": ["Scope validation", "Make-or-buy analysis", "Team-development assessment", "Earned value analysis"], "correct": 1, "explanation": "Make-or-buy analysis compares internal provision and external procurement. It can include strategic and capability considerations as well as direct costs.", "type": "mcq"}, {"id": "M157", "chapter": 12, "topic": "Fixed-price contracts", "section": "Types of Contracts", "stem": "A buyer has a clear specification and agrees a fixed total price for the defined work. If the seller's own costs rise without an approved scope change, who normally bears that cost-overrun risk?", "options": ["Neither party because fixed price removes all risk", "The project sponsor personally", "The buyer automatically", "The seller"], "correct": 3, "explanation": "For the defined scope, a fixed-price arrangement generally places more cost-overrun risk on the seller. Changes and contract terms can alter responsibilities.", "type": "mcq"}, {"id": "M158", "chapter": 12, "topic": "Cost-reimbursable contracts", "section": "Types of Contracts", "stem": "The scope is uncertain and the buyer agrees to reimburse allowable actual costs plus a fee. Compared with a firm fixed price for the same work, which party generally carries more cost uncertainty?", "options": ["The seller exclusively", "Neither party has cost exposure.", "The buyer", "The buyer carries none because costs are documented."], "correct": 2, "explanation": "Cost-reimbursable arrangements place more actual-cost risk on the buyer. Cost visibility and controls help but do not eliminate uncertainty.", "type": "mcq"}, {"id": "M159", "chapter": 12, "topic": "Time and material", "section": "Types of Contracts", "stem": "Consultants charge agreed hourly rates plus specified material costs, while the total number of hours is uncertain. Which contract form most directly describes the arrangement?", "options": ["Cost-free partnership", "Firm fixed price for the entire job", "Time and material", "Purchase by final outcome only"], "correct": 2, "explanation": "Time-and-material contracts combine fixed rates with uncertain quantities. A fixed hourly rate does not make the total project price fixed.", "type": "mcq"}, {"id": "M160", "chapter": 12, "topic": "Procurement statement of work", "section": "Planning Procurement Management", "stem": "Prospective suppliers need enough detail about the work to decide whether they can perform it and prepare a suitable price. Which document should describe the contracted work and deliverables?", "options": ["Earned value chart", "Employee performance review", "Project communications log", "Procurement statement of work"], "correct": 3, "explanation": "A procurement SOW defines the work to be obtained in enough detail for potential sellers. It supports a common understanding of the procurement's scope.", "type": "mcq"}, {"id": "M161", "chapter": 12, "topic": "Request for proposal", "section": "Planning Procurement Management", "stem": "A buyer wants suppliers to propose how they would solve a business problem, including approach and capability, rather than quote an identical commodity. Which request is most appropriate?", "options": ["Project closure notice", "Request for proposal", "Request for a final invoice", "Routine acceptance certificate"], "correct": 1, "explanation": "An RFP solicits proposed solutions and approaches. A request for quotation is more appropriate when requirements are clear and a price quote is central.", "type": "mcq"}, {"id": "M162", "chapter": 12, "topic": "Request for quotation", "section": "Planning Procurement Management", "stem": "A buyer needs a specified quantity of identical standard devices and primarily wants comparable prices for clearly defined items. Which procurement document is most appropriate?", "options": ["Request for a project charter", "Request for a retrospective", "Stakeholder engagement plan", "Request for quotation"], "correct": 3, "explanation": "An RFQ is useful for well-defined products or services where price comparison is central. An RFP invites broader solution proposals.", "type": "mcq"}, {"id": "M163", "chapter": 12, "topic": "Source selection", "section": "Conducting Procurements", "stem": "A selection team agrees technical, management, and cost criteria before evaluating supplier proposals. What is the main benefit of applying this defined evaluation model consistently?", "options": ["A guarantee that the cheapest bid will always win", "A more transparent and comparable basis for selection", "Removal of the need to examine supplier capability", "Proof that every proposal meets all requirements"], "correct": 1, "explanation": "Defined criteria promote consistency and help evaluate trade-offs. They do not automatically favor the lowest price or guarantee qualification.", "type": "mcq"}, {"id": "M164", "chapter": 12, "topic": "Bidder conferences", "section": "Conducting Procurements", "stem": "Several prospective suppliers have questions about ambiguous requirements. The buyer holds a shared clarification session before proposals are submitted. What is the principal purpose of this bidder conference?", "options": ["Formally close an already completed contract.", "Give prospective sellers a common understanding of the procurement.", "Allow one preferred seller to change the requirements privately.", "Replace all written procurement requirements with informal promises."], "correct": 1, "explanation": "Bidder conferences clarify requirements and help ensure a fair, shared understanding. Resulting clarifications should be handled consistently for the participating suppliers.", "type": "mcq"}, {"id": "M165", "chapter": 12, "topic": "Controlling procurements", "section": "Controlling Procurements", "stem": "After contract award, the manager monitors seller performance, reviews proposed changes, and checks that agreed obligations are fulfilled. Which procurement process most directly covers this work?", "options": ["Identifying stakeholders only", "Conducting project initiation", "Controlling procurements", "Strategic portfolio selection"], "correct": 2, "explanation": "Controlling procurements manages the buyer-seller relationship and performance under the contract, including changes and closure activities. Award alone does not end procurement management.", "type": "mcq"}, {"id": "M166", "chapter": 12, "topic": "Constructive change", "section": "Controlling Procurements", "stem": "A project employee informally tells a supplier to do extra work outside the agreed contract, believing a verbal request has no consequences. What is the most appropriate concern?", "options": ["Verbal directions can never affect contractual obligations.", "The supplier automatically must do unlimited extra work for free.", "The instruction may create a constructive change and contractual consequences.", "Only written invoices can ever change project scope."], "correct": 2, "explanation": "Informal directions can create constructive changes or disputes. Team members should respect contract authority and change procedures rather than assume informal requests are harmless.", "type": "mcq"}, {"id": "M167", "chapter": 12, "topic": "Make-or-buy break-even", "section": "Planning Procurement Management", "stem": "Buying a tool costs $18,000 upfront plus $200 per month; renting costs $800 per month. Ignore all other costs and discounting. At how many months do the total costs become equal?", "options": ["90 months", "30 months", "18 months", "22.5 months"], "correct": 1, "explanation": "18,000 + 200m = 800m, so m = 18,000/600 = 30. Beyond 30 months buying is cheaper under these assumptions.", "type": "mcq"}, {"id": "M168", "chapter": 12, "topic": "Contract closure", "section": "Controlling Procurements", "stem": "A vendor completes the work, but acceptance records and unresolved claims remain. Which action best supports proper procurement closure before treating the relationship as finished?", "options": ["Delete procurement records as soon as coding stops.", "Assume the final code commit settles all claims.", "Release every payment without checking contract conditions.", "Verify completion and resolve or appropriately handle outstanding contractual matters."], "correct": 3, "explanation": "Closure requires attention to completion, acceptance, records, and outstanding obligations or claims according to the contract. Technical completion alone is not sufficient.", "type": "mcq"}, {"id": "M169", "chapter": 13, "topic": "Stakeholder identification", "section": "Identifying Stakeholders", "stem": "A new system affects employees, customers, a regulator, and a supplier. Only employees are currently listed. What should the manager do to establish a more complete stakeholder view?", "options": ["Limit the list to people employed by the organization.", "Exclude regulators because they do not write code.", "Include only groups expected to support the project.", "Include relevant internal and external affected parties."], "correct": 3, "explanation": "Stakeholders can be internal or external and supportive or opposed. Being affected or able to affect the project matters, not employee status alone.", "type": "mcq"}, {"id": "M170", "chapter": 13, "topic": "Stakeholder register", "section": "Identifying Stakeholders", "stem": "A team records stakeholder identities, roles, contact information, interests, and classifications so later engagement planning has a foundation. Which artifact is being developed?", "options": ["WBS dictionary", "Cost baseline", "Stakeholder register", "Risk breakdown structure"], "correct": 2, "explanation": "A stakeholder register records identification, assessment, and classification information. It supports analysis and engagement planning.", "type": "mcq"}, {"id": "M171", "chapter": 13, "topic": "Power-interest grid", "section": "Planning Stakeholder Engagement", "stem": "An executive has both high decision power and high interest in the project's outcome. In a typical power-interest grid, what general engagement strategy is appropriate?", "options": ["Keep informed but avoid direct engagement", "Treat as low priority because authority is high", "Monitor with minimal effort", "Manage closely"], "correct": 3, "explanation": "High-power, high-interest stakeholders normally require close management. The grid guides attention but should still be adapted to the person's actual needs.", "type": "mcq"}, {"id": "M172", "chapter": 13, "topic": "Keep satisfied", "section": "Planning Stakeholder Engagement", "stem": "A senior official has substantial power over the project but little interest in day-to-day detail. What broad power-interest strategy is usually appropriate for this stakeholder?", "options": ["Keep satisfied", "Send every technical log without context", "Assume no engagement is needed", "Monitor with minimal effort only"], "correct": 0, "explanation": "High power with low interest generally calls for keeping the stakeholder satisfied. Overwhelming them with unnecessary detail can be unhelpful.", "type": "mcq"}, {"id": "M173", "chapter": 13, "topic": "Keep informed", "section": "Planning Stakeholder Engagement", "stem": "A user group has limited formal power but strong interest because the system affects daily work. What broad strategy fits its position on a power-interest grid?", "options": ["Manage only through procurement contracts", "Assume it has high authority over every decision", "Keep informed", "Ignore entirely"], "correct": 2, "explanation": "Low-power, high-interest stakeholders should generally be kept informed. Their knowledge and concerns can still be valuable despite limited formal authority.", "type": "mcq"}, {"id": "M174", "chapter": 13, "topic": "Monitoring low-power stakeholders", "section": "Planning Stakeholder Engagement", "stem": "A peripheral group currently has little power and little interest in the project. Which broad strategy fits a power-interest grid while allowing circumstances to change later?", "options": ["Give it automatic approval authority.", "Monitor with appropriate minimal effort.", "Exclude it permanently from every future review.", "Send all confidential project records daily."], "correct": 1, "explanation": "Low-power, low-interest stakeholders typically need monitoring rather than intensive management. Their position may change, so this is not permanent exclusion.", "type": "mcq"}, {"id": "M175", "chapter": 13, "topic": "Engagement assessment", "section": "Planning Stakeholder Engagement", "stem": "The team compares each stakeholder's current engagement with the level needed for project success. Which tool is particularly suited to displaying these current and desired positions?", "options": ["Activity-on-arrow network", "Earned value chart", "Resource histogram", "Stakeholder engagement assessment matrix"], "correct": 3, "explanation": "An engagement assessment matrix compares current and desired engagement levels, helping identify gaps and targeted actions.", "type": "mcq"}, {"id": "M176", "chapter": 13, "topic": "Resistant vs. unaware", "section": "Planning Stakeholder Engagement", "stem": "A department understands the proposed change but actively opposes it because of expected disruption. Which engagement classification best describes the department, rather than one that does not yet know about the project?", "options": ["Unaware", "Leading", "Supportive", "Resistant"], "correct": 3, "explanation": "Resistant stakeholders know about the project but oppose it. Unaware stakeholders lack awareness; supportive and leading stakeholders have different levels of positive engagement.", "type": "mcq"}, {"id": "M177", "chapter": 13, "topic": "Managing engagement", "section": "Managing Stakeholder Engagement", "stem": "A manager meets concerned users, clarifies expectations, and works through objections so they can contribute constructively. Which process most directly describes this active interaction?", "options": ["Managing stakeholder engagement", "Performing portfolio selection", "Conducting product-only quality tests", "Creating the original cost baseline"], "correct": 0, "explanation": "Managing engagement involves communication and interaction to address expectations and issues. It goes beyond merely identifying stakeholders or sending reports.", "type": "mcq"}, {"id": "M178", "chapter": 13, "topic": "Issue log", "section": "Managing Stakeholder Engagement", "stem": "A stakeholder raises an unresolved access problem that is already occurring. The manager records its owner, status, and resolution action. Which artifact most directly tracks this current matter?", "options": ["Procurement pricing schedule", "Risk register only as an uncertain future event", "Issue log", "Product vision statement"], "correct": 2, "explanation": "An issue log tracks current problems and their resolution. A risk register focuses on uncertainty; a realized problem needs issue handling.", "type": "mcq"}, {"id": "M179", "chapter": 13, "topic": "Monitoring engagement", "section": "Monitoring Stakeholder Engagement", "stem": "A previously supportive director stops attending reviews after a reorganization. The manager reassesses engagement and changes the approach. Which process is most directly illustrated?", "options": ["Freezing the stakeholder plan permanently", "Monitoring stakeholder engagement", "Scope validation", "Closing the project automatically"], "correct": 1, "explanation": "Monitoring engagement assesses relationship and engagement changes and adjusts strategies. A stakeholder assessment is not a once-only activity.", "type": "mcq"}, {"id": "M180", "chapter": 13, "topic": "Sensitive information", "section": "Planning Stakeholder Engagement", "stem": "An engagement plan includes candid assessments of individual influence and resistance. The team considers posting the entire plan publicly. Which handling is most appropriate for this sensitive analysis?", "options": ["Give all outside suppliers unrestricted access by default.", "Share sensitive assessments only with appropriate authorized recipients.", "Publish every personal assessment regardless of purpose.", "Delete all stakeholder analysis to avoid any sensitivity."], "correct": 1, "explanation": "Some stakeholder analysis is sensitive and should be handled carefully. Appropriate access preserves useful planning without unnecessary disclosure.", "type": "mcq"}, {"id": "M181", "chapter": 13, "topic": "Agile stakeholder involvement", "section": "Considerations for Agile/Adaptive Environments", "stem": "An agile team delivers frequent increments and needs quick feedback to reprioritize future work. Which stakeholder approach best supports this adaptive setting?", "options": ["Wait until final delivery for all customer feedback.", "Treat the initial backlog as permanently fixed.", "Frequent collaboration and timely decisions from relevant stakeholders.", "Replace the product owner with an annual status report."], "correct": 2, "explanation": "Adaptive work benefits from frequent stakeholder involvement and quick feedback. Delaying feedback undermines the ability to adjust priorities and deliver value.", "type": "mcq"}, {"id": "T182", "chapter": 1, "topic": "True / false", "section": "Chapter review", "stem": "A project must be short in duration to qualify as temporary.", "options": ["True", "False"], "correct": 1, "explanation": "Temporary means it has a beginning and an end. A project can last years.", "type": "tf"}, {"id": "T183", "chapter": 1, "topic": "True / false", "section": "Chapter review", "stem": "A portfolio may contain projects that are not directly related to one another.", "options": ["True", "False"], "correct": 0, "explanation": "The link is contribution to organizational strategy; a program instead coordinates related work for combined benefits.", "type": "tf"}, {"id": "T184", "chapter": 2, "topic": "True / false", "section": "Chapter review", "stem": "The three spheres are scope, schedule, and cost.", "options": ["True", "False"], "correct": 1, "explanation": "The three-sphere model is business, organization, and technology. Scope, time, and cost are the classical triple constraint.", "type": "tf"}, {"id": "T185", "chapter": 2, "topic": "True / false", "section": "Chapter review", "stem": "A product can continue in use after the project that created it closes.", "options": ["True", "False"], "correct": 0, "explanation": "Product life cycles can extend beyond the delivery project into operation, maintenance, and retirement.", "type": "tf"}, {"id": "T186", "chapter": 3, "topic": "True / false", "section": "Chapter review", "stem": "Monitoring and controlling starts only after all execution has ended.", "options": ["True", "False"], "correct": 1, "explanation": "It operates alongside and across other management activities as the project progresses.", "type": "tf"}, {"id": "T187", "chapter": 3, "topic": "True / false", "section": "Chapter review", "stem": "A sprint retrospective focuses on improving how the team works.", "options": ["True", "False"], "correct": 0, "explanation": "The review examines the product increment; the retrospective examines the team’s process.", "type": "tf"}, {"id": "T188", "chapter": 4, "topic": "True / false", "section": "Chapter review", "stem": "A positive NPV means discounted benefits exceed discounted costs at the chosen rate.", "options": ["True", "False"], "correct": 0, "explanation": "NPV nets discounted inflows and outflows. A positive result indicates net value under the assumptions used.", "type": "tf"}, {"id": "T189", "chapter": 4, "topic": "True / false", "section": "Chapter review", "stem": "Once approved, a project baseline can never be changed.", "options": ["True", "False"], "correct": 1, "explanation": "Approved changes can update baselines through established change control. Approval makes a baseline controlled, not immutable.", "type": "tf"}, {"id": "T190", "chapter": 5, "topic": "True / false", "section": "Chapter review", "stem": "Formal customer acceptance of deliverables is the central purpose of scope validation.", "options": ["True", "False"], "correct": 0, "explanation": "Quality control checks correctness; scope validation obtains formal acceptance.", "type": "tf"}, {"id": "T191", "chapter": 5, "topic": "True / false", "section": "Chapter review", "stem": "A WBS is primarily a diagram of activity sequence and dependencies.", "options": ["True", "False"], "correct": 1, "explanation": "A WBS decomposes project work around deliverables. A network diagram depicts scheduling dependencies.", "type": "tf"}, {"id": "T192", "chapter": 6, "topic": "True / false", "section": "Chapter review", "stem": "The critical path is the shortest path through a project network.", "options": ["True", "False"], "correct": 1, "explanation": "It is the longest duration path and determines earliest finish under the network assumptions.", "type": "tf"}, {"id": "T193", "chapter": 6, "topic": "True / false", "section": "Chapter review", "stem": "Fast tracking can increase rework risk by overlapping work originally planned in sequence.", "options": ["True", "False"], "correct": 0, "explanation": "Overlap may shorten the schedule but exposes later work to changes in unfinished predecessor work.", "type": "tf"}, {"id": "T194", "chapter": 7, "topic": "True / false", "section": "Chapter review", "stem": "A CPI below 1 indicates favorable cost efficiency.", "options": ["True", "False"], "correct": 1, "explanation": "CPI = EV/AC. Below 1 means less budgeted work value is earned than money spent.", "type": "tf"}, {"id": "T195", "chapter": 7, "topic": "True / false", "section": "Chapter review", "stem": "Sunk costs should by themselves justify continuing an uneconomic project.", "options": ["True", "False"], "correct": 1, "explanation": "Past unrecoverable spending is not a future benefit. Forward decisions should consider relevant future costs and benefits.", "type": "tf"}, {"id": "T196", "chapter": 8, "topic": "True / false", "section": "Chapter review", "stem": "A product with fewer features can still have high quality.", "options": ["True", "False"], "correct": 0, "explanation": "Grade and quality differ. A simple product can meet requirements and be fit for use.", "type": "tf"}, {"id": "T197", "chapter": 8, "topic": "True / false", "section": "Chapter review", "stem": "Warranty repair after delivery is normally a prevention cost.", "options": ["True", "False"], "correct": 1, "explanation": "It is an external failure cost because the defect affected a delivered product.", "type": "tf"}, {"id": "T198", "chapter": 9, "topic": "True / false", "section": "Chapter review", "stem": "Resource leveling can increase project duration.", "options": ["True", "False"], "correct": 0, "explanation": "Resolving over-allocation may shift activities and move the finish date.", "type": "tf"}, {"id": "T199", "chapter": 9, "topic": "True / false", "section": "Chapter review", "stem": "Expert power requires formal authority over employee salaries.", "options": ["True", "False"], "correct": 1, "explanation": "Expert power comes from knowledge or skill, not control over employment rewards.", "type": "tf"}, {"id": "T200", "chapter": 10, "topic": "True / false", "section": "Chapter review", "stem": "An eight-person team has 28 potential two-way communication channels.", "options": ["True", "False"], "correct": 0, "explanation": "8×7/2 = 28 distinct pairs.", "type": "tf"}, {"id": "T201", "chapter": 10, "topic": "True / false", "section": "Chapter review", "stem": "Sending an email proves the recipients understood its content.", "options": ["True", "False"], "correct": 1, "explanation": "Push delivery does not guarantee reading or understanding; feedback may be needed.", "type": "tf"}, {"id": "T202", "chapter": 11, "topic": "True / false", "section": "Chapter review", "stem": "All project risks necessarily have negative effects.", "options": ["True", "False"], "correct": 1, "explanation": "Risk includes opportunities with potentially positive effects as well as threats.", "type": "tf"}, {"id": "T203", "chapter": 11, "topic": "True / false", "section": "Chapter review", "stem": "A secondary risk is a new risk introduced by a risk response.", "options": ["True", "False"], "correct": 0, "explanation": "A residual risk instead remains after the response.", "type": "tf"}, {"id": "T204", "chapter": 12, "topic": "True / false", "section": "Chapter review", "stem": "A fixed hourly consulting rate necessarily fixes the total contract price.", "options": ["True", "False"], "correct": 1, "explanation": "Total time-and-material cost also depends on hours and materials used.", "type": "tf"}, {"id": "T205", "chapter": 12, "topic": "True / false", "section": "Chapter review", "stem": "Fixed-price contracts generally place defined-scope cost-overrun risk on the seller.", "options": ["True", "False"], "correct": 0, "explanation": "This general allocation depends on contract terms and excludes approved changes to the work.", "type": "tf"}, {"id": "T206", "chapter": 13, "topic": "True / false", "section": "Chapter review", "stem": "Only people who support a project should appear in the stakeholder register.", "options": ["True", "False"], "correct": 1, "explanation": "Opponents and other affected parties are also stakeholders.", "type": "tf"}, {"id": "T207", "chapter": 13, "topic": "True / false", "section": "Chapter review", "stem": "Stakeholder engagement should be reassessed as the project and organization change.", "options": ["True", "False"], "correct": 0, "explanation": "Power, interest, and engagement can change; monitoring supports adjustments.", "type": "tf"}]};
